const e="hsk",t=6,n=[{num:1,title:"孩子给我们的启示",points:[{id:"HSK6.01.1",name:"动词“巴不得”",pinyin:"bābude",type:"动词/固定用法",explainEn:"Use 巴不得 to mean “wish very strongly that something would happen”.",structure:"巴不得 + 小句",examples:[{zh:"我巴不得马上放假。",en:"I wish the holiday could start right now.",py:"Wǒ bābude mǎshàng fàngjià."},{zh:"他巴不得孩子早点儿回家。",en:"He really wishes his child would come home earlier.",py:"Tā bābude háizi zǎo diǎnr huíjiā."},{zh:"有人帮我，我巴不得呢。",en:"If someone helps me, I would be delighted.",py:"Yǒu rén bāng wǒ, wǒ bābude ne."}],exercises:[{q:"填空：我___马上见到他。",a:"巴不得",instr:"填空",instrEn:"Fill in the blank",body:"我___马上见到他。"},{q:"翻译：He really wishes his child would come home.",a:"他巴不得孩子早点儿回家。",instr:"翻译",instrEn:"Translate",body:"He really wishes his child would come home."},{q:"选择：表示非常盼望，用（巴不得 / 未免）。",a:"巴不得",instr:"选择",instrEn:"Choose",body:"表示非常盼望，用（巴不得 / 未免）。"}],note:"多用于口语，表示迫切希望；愿望通常是说话人认为很好的事。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bābude + Clause = wish very much that …",noteEn:"Mostly spoken; expresses an eager wish, usually for something the speaker sees as good.",typeEn:"Verb / Set usage"},{id:"HSK6.01.2",name:"“别提多……了”表示程度很深",pinyin:"biétí duō ... le",type:"程度结构",explainEn:"Use 别提多…了 to mean “extremely / you can't imagine how…”.",structure:"别提 + 多 + 形容词/心理动词 + 了",examples:[{zh:"听到这个消息，我别提多高兴了。",en:"I was extremely happy to hear the news.",py:"Tīngdào zhège xiāoxi, wǒ biétí duō gāoxìng le."},{zh:"那天山上别提多冷了。",en:"It was unbelievably cold on the mountain that day.",py:"Nà tiān shān shang biétí duō lěng le."},{zh:"孩子回来以后，她别提多放心了。",en:"She was extremely relieved after the child came back.",py:"Háizi huílai yǐhòu, tā biétí duō fàngxīn le."}],exercises:[{q:"填空：我___多高兴___。",a:"别提；了",instr:"填空",instrEn:"Fill in the blank",body:"我___多高兴___。"},{q:"翻译：It was unbelievably cold that day.",a:"那天别提多冷了。",instr:"翻译",instrEn:"Translate",body:"It was unbelievably cold that day."},{q:"用该结构改写：妈妈非常放心。",a:"妈妈别提多放心了。"}],note:"带有夸张和感情色彩，常用于口语。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"biétí + duō + Adj / mental verb + le = you can't imagine how … / extremely …",noteEn:"Exaggerated and emotional; common in speech.",typeEn:"Degree structure"},{id:"HSK6.01.3",name:"具有语体差别的同义词",pinyin:"jùyǒu yǔtǐ chābié de tóngyìcí",type:"词汇/语体",explainEn:"Words with similar meanings can differ in style: some are formal, others are conversational.",structure:"书面词 ↔ 口语词：将↔把；即↔就是；令↔让等",examples:[{zh:"请将材料交给老师。",en:"Please give the material to the teacher.",py:"Qǐng jiāng cáiliào jiāo gěi lǎoshī."},{zh:"你把材料给老师吧。",en:"Give the material to the teacher.",py:"Nǐ bǎ cáiliào gěi lǎoshī ba."},{zh:"通知写道，会议将于九点开始。",en:"The notice says the meeting will begin at nine.",py:"Tōngzhī xiědào, huìyì jiāng yú jiǔ diǎn kāishǐ."}],exercises:[{q:"选择更书面的词：___材料交给老师。（将/把）",a:"将"},{q:"把“即”换成更口语的词。",a:"就是"},{q:"判断：正式通知里“将于九点开始”是否自然？",a:"自然"}],note:"高级学习要注意词义相近但语体不同；正式写作与口语应选择合适表达。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Formal ↔ spoken: jiāng ↔ bǎ; jí ↔ jiùshì; lìng ↔ ràng, etc.",noteEn:"At higher levels, watch for near-synonyms that differ in register; pick the formal or spoken one to suit the context.",typeEn:"Vocabulary / Register"}]},{num:2,title:"父母之爱",points:[{id:"HSK6.02.1",name:"动词“恨不得”",pinyin:"hènbude",type:"动词/固定用法",explainEn:"Use 恨不得 to mean “wish very strongly / cannot wait to…”.",structure:"恨不得 + 立刻/马上 + 动词",examples:[{zh:"我恨不得现在就回家。",en:"I wish I could go home right now.",py:"Wǒ hènbude xiànzài jiù huíjiā."},{zh:"他急得恨不得马上知道结果。",en:"He was so anxious that he wished he knew the result immediately.",py:"Tā jí de hènbude mǎshàng zhīdào jiéguǒ."},{zh:"天气太热，我恨不得一天都待在空调房里。",en:"It is so hot that I wish I could stay in an air-conditioned room all day.",py:"Tiānqì tài rè, wǒ hènbude yì tiān dōu dāi zài kōngtiáo fáng li."}],exercises:[{q:"填空：我___马上看到结果。",a:"恨不得",instr:"填空",instrEn:"Fill in the blank",body:"我___马上看到结果。"},{q:"翻译：I wish I could go home right now.",a:"我恨不得现在就回家。",instr:"翻译",instrEn:"Translate",body:"I wish I could go home right now."},{q:"选择：强烈希望马上发生，用（恨不得 / 不妨）。",a:"恨不得",instr:"选择",instrEn:"Choose",body:"强烈希望马上发生，用（恨不得 / 不妨）。"}],note:"和“巴不得”接近；“恨不得”常带急切、焦急或强烈感情。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"hènbude + lìkè/mǎshàng + Verb = can't wait to … right now",noteEn:"Close to 巴不得; 恨不得 often carries urgency, anxiety or strong feeling.",typeEn:"Verb / Set usage"},{id:"HSK6.02.2",name:"副词“顿时”",pinyin:"dùnshí",type:"副词",explainEn:"Use 顿时 to mean “suddenly / immediately at that moment”.",structure:"情况 + 顿时 + 变化",examples:[{zh:"听到好消息，大家顿时高兴起来。",en:"Everyone became happy at once after hearing the good news.",py:"Tīngdào hǎo xiāoxi, dàjiā dùnshí gāoxìng qilai."},{zh:"门一打开，房间里顿时亮了。",en:"As soon as the door opened, the room suddenly became bright.",py:"Mén yì dǎkāi, fángjiān li dùnshí liàng le."},{zh:"他的话让我顿时明白了。",en:"His words made me understand immediately.",py:"Tā de huà ràng wǒ dùnshí míngbai le."}],exercises:[{q:"填空：听到消息，大家___安静下来。",a:"顿时",instr:"填空",instrEn:"Fill in the blank",body:"听到消息，大家___安静下来。"},{q:"翻译：The room suddenly became bright.",a:"房间里顿时亮了。",instr:"翻译",instrEn:"Translate",body:"The room suddenly became bright."},{q:"选择：表示短时间内突然变化，用（顿时 / 向来）。",a:"顿时",instr:"选择",instrEn:"Choose",body:"表示短时间内突然变化，用（顿时 / 向来）。"}],note:"多说明某件事发生后，状态马上发生变化。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Situation + dùnshí + change = … at once / suddenly",noteEn:"Usually says that right after something happens, the state changes at once.",typeEn:"Adverb"},{id:"HSK6.02.3",name:"副词“不由得”",pinyin:"bùyóude",type:"副词",explainEn:"Use 不由得 to mean “cannot help doing something”.",structure:"不由得 + 动词",examples:[{zh:"听到这个故事，我不由得笑了。",en:"I could not help laughing when I heard the story.",py:"Tīngdào zhège gùshi, wǒ bùyóude xiào le."},{zh:"看到老照片，她不由得想起了小时候。",en:"Seeing the old photos, she could not help remembering her childhood.",py:"Kàndào lǎo zhàopiàn, tā bùyóude xiǎngqǐle xiǎoshíhou."},{zh:"他说得太感人，大家不由得流下了眼泪。",en:"He spoke so movingly that everyone could not help crying.",py:"Tā shuō de tài gǎnrén, dàjiā bùyóude liúxiàle yǎnlèi."}],exercises:[{q:"填空：听完故事，我___笑了。",a:"不由得",instr:"填空",instrEn:"Fill in the blank",body:"听完故事，我___笑了。"},{q:"翻译：She could not help remembering her childhood.",a:"她不由得想起了小时候。",instr:"翻译",instrEn:"Translate",body:"She could not help remembering her childhood."},{q:"选择：表示控制不住地做某事，用（不由得 / 务必）。",a:"不由得",instr:"选择",instrEn:"Choose",body:"表示控制不住地做某事，用（不由得 / 务必）。"}],note:"表示动作自然发生，并非有意去做。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùyóude + Verb = can't help doing …",noteEn:"The action happens naturally, not on purpose.",typeEn:"Adverb"}]},{num:3,title:"一盒月饼",points:[{id:"HSK6.03.1",name:"量词“番”",pinyin:"fān",type:"动量词",explainEn:"Use 番 after an action or noun to mean “a round / an occasion of effort, discussion, thought, etc.”.",structure:"一番 + 名词/动词性成分",examples:[{zh:"经过一番讨论，我们终于决定了。",en:"After a round of discussion, we finally decided.",py:"Jīngguò yì fān tǎolùn, wǒmen zhōngyú juédìng le."},{zh:"他为这件事费了一番心思。",en:"He put a lot of thought into this matter.",py:"Tā wèi zhè jiàn shì fèile yì fān xīnsi."},{zh:"老师对我进行了一番鼓励。",en:"The teacher gave me some encouragement.",py:"Lǎoshī duì wǒ jìnxíngle yì fān gǔlì."}],exercises:[{q:"填空：经过一___讨论，我们决定了。",a:"番",instr:"填空",instrEn:"Fill in the blank",body:"经过一___讨论，我们决定了。"},{q:"翻译：He put a lot of thought into this matter.",a:"他为这件事费了一番心思。",instr:"翻译",instrEn:"Translate",body:"He put a lot of thought into this matter."},{q:"选择：常说（一番努力 / 一番桌子）。",a:"一番努力",instr:"选择",instrEn:"Choose",body:"常说（一番努力 / 一番桌子）。"}],note:"常与“讨论、努力、考虑、心思、解释”等搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yì fān + Noun / verbal phrase = a round of … (effort, talk, thought)",noteEn:"Often paired with 讨论, 努力, 考虑, 心思, 解释, etc.",typeEn:"Verbal measure word"},{id:"HSK6.03.2",name:"副词“过于”",pinyin:"guòyú",type:"副词",explainEn:"Use 过于 before an adjective or verb to mean “too / excessively”.",structure:"过于 + 形容词/心理动词",examples:[{zh:"你不必过于担心。",en:"You do not need to worry too much.",py:"Nǐ búbì guòyú dānxīn."},{zh:"这个要求过于严格。",en:"This requirement is too strict.",py:"Zhège yāoqiú guòyú yángé."},{zh:"过于依赖手机不是好事。",en:"Relying too much on a phone is not a good thing.",py:"Guòyú yīlài shǒujī bú shì hǎoshì."}],exercises:[{q:"填空：你不必___担心。",a:"过于",instr:"填空",instrEn:"Fill in the blank",body:"你不必___担心。"},{q:"翻译：This requirement is too strict.",a:"这个要求过于严格。",instr:"翻译",instrEn:"Translate",body:"This requirement is too strict."},{q:"选择：表示“too dependent”用（过于依赖 / 顿时依赖）。",a:"过于依赖",instr:"选择",instrEn:"Choose",body:"表示“too dependent”用（过于依赖 / 顿时依赖）。"}],note:"比“太”更正式，常用于书面语。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"guòyú + Adj / mental verb = too … / excessively …",noteEn:"More formal than 太; common in writing.",typeEn:"Adverb"},{id:"HSK6.03.3",name:"“……着呢”表示程度/状态",pinyin:"... zhe ne",type:"助词结构",explainEn:"Use …着呢 to strongly emphasize a state: “very / far from…”.",structure:"形容词/状态 + 着呢",examples:[{zh:"时间还早着呢。",en:"It is still very early.",py:"Shíjiān hái zǎo zhene."},{zh:"这件事复杂着呢。",en:"This matter is really complicated.",py:"Zhè jiàn shì fùzá zhene."},{zh:"他身体好着呢，你别担心。",en:"He is perfectly healthy, so do not worry.",py:"Tā shēntǐ hǎo zhene, nǐ bié dānxīn."}],exercises:[{q:"填空：时间还早___。",a:"着呢",instr:"填空",instrEn:"Fill in the blank",body:"时间还早___。"},{q:"翻译：This matter is really complicated.",a:"这件事复杂着呢。",instr:"翻译",instrEn:"Translate",body:"This matter is really complicated."},{q:"用“着呢”强调：他身体很好。",a:"他身体好着呢。"}],note:"口语色彩较强，用来加强状态或程度。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Adj / state + zhene = very … indeed",noteEn:"Strongly colloquial; intensifies a state or degree.",typeEn:"Particle structure"}]},{num:4,title:"完美的胜利",points:[{id:"HSK6.04.1",name:"副词“乘机”",pinyin:"chéngjī",type:"副词",explainEn:"Use 乘机 to mean “take the opportunity to…”.",structure:"乘机 + 动词",examples:[{zh:"我去北京出差，乘机看了一个老朋友。",en:"I went to Beijing on business and took the opportunity to visit an old friend.",py:"Wǒ qù Běijīng chūchāi, chéngjī kànle yí ge lǎo péngyou."},{zh:"大家休息时，他乘机问了老师几个问题。",en:"During the break, he took the opportunity to ask the teacher some questions.",py:"Dàjiā xiūxi shí, tā chéngjī wènle lǎoshī jǐ ge wèntí."},{zh:"趁会议结束，我乘机介绍了自己的想法。",en:"When the meeting ended, I took the chance to introduce my idea.",py:"Chèn huìyì jiéshù, wǒ chéngjī jièshàole zìjǐ de xiǎngfǎ."}],exercises:[{q:"填空：出差时，我___见了朋友。",a:"乘机",instr:"填空",instrEn:"Fill in the blank",body:"出差时，我___见了朋友。"},{q:"翻译：He took the opportunity to ask the teacher.",a:"他乘机问了老师几个问题。",instr:"翻译",instrEn:"Translate",body:"He took the opportunity to ask the teacher."},{q:"选择：表示抓住机会，用（乘机 / 不料）。",a:"乘机",instr:"选择",instrEn:"Choose",body:"表示抓住机会，用（乘机 / 不料）。"}],note:"与“趁机”接近，“乘机”较书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"chéngjī + Verb = take the chance to …",noteEn:"Close to 趁机; 乘机 is more formal.",typeEn:"Adverb"},{id:"HSK6.04.2",name:"连词“不料”",pinyin:"bùliào",type:"连词/副词",explainEn:"Use 不料 to introduce an unexpected result: “unexpectedly / to one's surprise”.",structure:"原来的计划/预期，不料 + 意外结果",examples:[{zh:"我以为他不会来，不料他第一个到了。",en:"I thought he would not come, but unexpectedly he arrived first.",py:"Wǒ yǐwéi tā bú huì lái, búliào tā dì-yī ge dào le."},{zh:"天气预报说晴天，不料下午下起了雨。",en:"The forecast said it would be sunny, but it unexpectedly rained in the afternoon.",py:"Tiānqì yùbào shuō qíngtiān, búliào xiàwǔ xiàqǐle yǔ."},{zh:"我们准备得很充分，不料还是出了问题。",en:"We prepared well, yet an unexpected problem still occurred.",py:"Wǒmen zhǔnbèi de hěn chōngfèn, búliào háishi chūle wèntí."}],exercises:[{q:"填空：我以为他不来，___他来了。",a:"不料",instr:"填空",instrEn:"Fill in the blank",body:"我以为他不来，___他来了。"},{q:"翻译：Unexpectedly, it rained in the afternoon.",a:"不料下午下起了雨。",instr:"翻译",instrEn:"Translate",body:"Unexpectedly, it rained in the afternoon."},{q:"连接：我们准备充分。结果还是出问题了。（用“不料”）",a:"我们准备得很充分，不料还是出了问题。",instr:"连接",instrEn:"Join the sentences",body:"我们准备充分。结果还是出问题了。（用“不料”）"}],note:"常用于叙述中，强调结果和预想相反。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Original plan / expectation, búliào + unexpected result = but, unexpectedly, …",noteEn:"Common in narration; stresses that the result is the opposite of what was expected.",typeEn:"Conjunction / Adverb"},{id:"HSK6.04.3",name:"副词“未免”",pinyin:"wèimiǎn",type:"副词",explainEn:"Use 未免 to mean “rather too / a bit too…”, often showing mild criticism.",structure:"未免 + 太/有点儿 + 形容词/动词",examples:[{zh:"你这样说未免太直接了。",en:"What you said is a bit too direct.",py:"Nǐ zhèyàng shuō wèimiǎn tài zhíjiē le."},{zh:"因为一点小事就放弃，未免太可惜了。",en:"Giving up over such a small matter is really a pity.",py:"Yīnwèi yìdiǎn xiǎoshì jiù fàngqì, wèimiǎn tài kěxī le."},{zh:"这个价格未免有点儿高。",en:"This price is rather high.",py:"Zhège jiàgé wèimiǎn yǒudiǎnr gāo."}],exercises:[{q:"填空：这个价格___太高了。",a:"未免",instr:"填空",instrEn:"Fill in the blank",body:"这个价格___太高了。"},{q:"翻译：That is a bit too direct.",a:"这未免太直接了。",instr:"翻译",instrEn:"Translate",body:"That is a bit too direct."},{q:"选择：带委婉批评用（未免 / 顿时）。",a:"未免",instr:"选择",instrEn:"Choose",body:"带委婉批评用（未免 / 顿时）。"}],note:"常用于评价某事“有点儿过头”，语气比直接批评更委婉。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wèimiǎn + tài/yǒudiǎnr + Adj/Verb = rather too … / a bit too …",noteEn:'Often used to judge something as "a bit too much" — gentler than open criticism.',typeEn:"Adverb"}]},{num:5,title:"学一门外语需要理由吗",points:[{id:"HSK6.05.1",name:"助词“而已”",pinyin:"éryǐ",type:"助词",explainEn:"Use 而已 after a statement to mean “only / nothing more”.",structure:"小句 + 而已",examples:[{zh:"我只是随便问问而已。",en:"I was only asking casually.",py:"Wǒ zhǐshì suíbiàn wènwen éryǐ."},{zh:"这只是一个建议而已。",en:"This is only a suggestion.",py:"Zhè zhǐshì yí ge jiànyì éryǐ."},{zh:"他开个玩笑而已，你别生气。",en:"He was only joking; do not be angry.",py:"Tā kāi ge wánxiào éryǐ, nǐ bié shēngqì."}],exercises:[{q:"填空：我只是问问___。",a:"而已",instr:"填空",instrEn:"Fill in the blank",body:"我只是问问___。"},{q:"翻译：This is only a suggestion.",a:"这只是一个建议而已。",instr:"翻译",instrEn:"Translate",body:"This is only a suggestion."},{q:"用“而已”改写：他只是开玩笑。",a:"他只是开个玩笑而已。"}],note:"放在句末，弱化事情的重要性或范围。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Clause + éryǐ = only … / that's all",noteEn:"Goes at the end of the sentence and plays down the importance or scope.",typeEn:"Particle"},{id:"HSK6.05.2",name:"连词“固然”",pinyin:"gùrán",type:"连词/副词",explainEn:"Use 固然 to admit one fact before adding another important point: “admittedly / it is true that…”.",structure:"固然 + A，但是/可是/不过 + B",examples:[{zh:"经验固然重要，但是态度也不能忽视。",en:"Experience is important, but attitude cannot be ignored.",py:"Jīngyàn gùrán zhòngyào, dànshì tàidu yě bù néng hūshì."},{zh:"钱固然重要，健康更重要。",en:"Money is important, but health is more important.",py:"Qián gùrán zhòngyào, jiànkāng gèng zhòngyào."},{zh:"这个办法固然简单，不过不一定适合所有人。",en:"This method is simple, but it may not suit everyone.",py:"Zhège bànfǎ gùrán jiǎndān, búguò bù yídìng shìhé suǒyǒu rén."}],exercises:[{q:"填空：经验___重要，但是态度也重要。",a:"固然",instr:"填空",instrEn:"Fill in the blank",body:"经验___重要，但是态度也重要。"},{q:"翻译：Money is important, but health is more important.",a:"钱固然重要，健康更重要。",instr:"翻译",instrEn:"Translate",body:"Money is important, but health is more important."},{q:"连接：方法简单。它不一定适合所有人。（用“固然”）",a:"这个办法固然简单，不过不一定适合所有人。",instr:"连接",instrEn:"Join the sentences",body:"方法简单。它不一定适合所有人。（用“固然”）"}],note:"先承认前一事实，再强调后面的补充或转折。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"gùrán + A, dànshì/kěshì/búguò + B = admittedly A, but B",noteEn:"First admits one fact, then stresses the addition or contrast that follows.",typeEn:"Conjunction / Adverb"},{id:"HSK6.05.3",name:"副词“无非”",pinyin:"wúfēi",type:"副词",explainEn:"Use 无非 to mean “nothing more than / simply”.",structure:"无非 + 是/就是 + 名词/小句",examples:[{zh:"他这么做无非是想帮你。",en:"He did this simply because he wanted to help you.",py:"Tā zhème zuò wúfēi shì xiǎng bāng nǐ."},{zh:"原因无非有两个。",en:"There are only two possible reasons.",py:"Yuányīn wúfēi yǒu liǎng ge."},{zh:"这件事无非就是时间问题。",en:"This is nothing more than a matter of time.",py:"Zhè jiàn shì wúfēi jiùshì shíjiān wèntí."}],exercises:[{q:"填空：他这么做___是想帮你。",a:"无非",instr:"填空",instrEn:"Fill in the blank",body:"他这么做___是想帮你。"},{q:"翻译：There are only two reasons.",a:"原因无非有两个。",instr:"翻译",instrEn:"Translate",body:"There are only two reasons."},{q:"选择：表示“nothing more than”用（无非 / 未免）。",a:"无非",instr:"选择",instrEn:"Choose",body:"表示“nothing more than”用（无非 / 未免）。"}],note:"表示范围很有限，常有“不过就是……”的意思。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wúfēi + shì/jiùshì + Noun/Clause = nothing more than …",noteEn:`The scope is very limited — often means "it's just…".`,typeEn:"Adverb"}]},{num:6,title:"当好职场插班生",points:[{id:"HSK6.06.1",name:"副词“唯独”",pinyin:"wéidú",type:"副词",explainEn:"Use 唯独 to mean “only / except for this one”.",structure:"唯独 + 人/事物 + 谓语",examples:[{zh:"大家都同意，唯独他反对。",en:"Everyone agreed; only he objected.",py:"Dàjiā dōu tóngyì, wéidú tā fǎnduì."},{zh:"什么都准备好了，唯独忘了带钥匙。",en:"Everything was ready except the key was forgotten.",py:"Shénme dōu zhǔnbèi hǎo le, wéidú wàngle dài yàoshi."},{zh:"其他问题都解决了，唯独这个最麻烦。",en:"All other problems were solved; only this one is troublesome.",py:"Qítā wèntí dōu jiějué le, wéidú zhège zuì máfan."}],exercises:[{q:"填空：大家都来了，___他没来。",a:"唯独",instr:"填空",instrEn:"Fill in the blank",body:"大家都来了，___他没来。"},{q:"翻译：Only this problem is troublesome.",a:"唯独这个问题最麻烦。",instr:"翻译",instrEn:"Translate",body:"Only this problem is troublesome."},{q:"选择：表示唯一例外，用（唯独 / 统统）。",a:"唯独",instr:"选择",instrEn:"Choose",body:"表示唯一例外，用（唯独 / 统统）。"}],note:"强调一个人或事物与其他情况不同。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wéidú + person/thing + predicate = only … / all except …",noteEn:"Stresses that one person or thing is different from all the others.",typeEn:"Adverb"},{id:"HSK6.06.2",name:"副词“明明”",pinyin:"míngmíng",type:"副词",explainEn:"Use 明明 when a fact is very clear, often followed by a surprising contradiction.",structure:"明明 + 明确事实，却/还 + 相反情况",examples:[{zh:"他明明知道答案，却不告诉我。",en:"He clearly knows the answer, yet he will not tell me.",py:"Tā míngmíng zhīdào dá'àn, què bú gàosu wǒ."},{zh:"明明是你迟到了，怎么怪别人？",en:"You were clearly late; how can you blame others?",py:"Míngmíng shì nǐ chídào le, zěnme guài biéren?"},{zh:"天气明明很好，他却带了两把伞。",en:"The weather is clearly good, yet he brought two umbrellas.",py:"Tiānqì míngmíng hěn hǎo, tā què dàile liǎng bǎ sǎn."}],exercises:[{q:"填空：他___知道答案，却不说。",a:"明明",instr:"填空",instrEn:"Fill in the blank",body:"他___知道答案，却不说。"},{q:"翻译：You were clearly late.",a:"明明是你迟到了。",instr:"翻译",instrEn:"Translate",body:"You were clearly late."},{q:"连接：天气很好。他却带了两把伞。",a:"天气明明很好，他却带了两把伞。",instr:"连接",instrEn:"Join the sentences",body:"天气很好。他却带了两把伞。"}],note:"常带不理解、不满或强调事实的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"míngmíng + obvious fact, què/hái + opposite situation = clearly …, yet …",noteEn:"Often carries puzzlement, annoyance, or emphasis on the obvious fact.",typeEn:"Adverb"},{id:"HSK6.06.3",name:"固定短语“大不了”",pinyin:"dàbuliǎo",type:"固定短语",explainEn:"Use 大不了 to mean “at worst / the worst that can happen is…”.",structure:"大不了 + 最坏结果",examples:[{zh:"失败了大不了再试一次。",en:"At worst, if we fail, we can try again.",py:"Shībài le dàbuliǎo zài shì yí cì."},{zh:"没车大不了走回去。",en:"If there is no car, at worst we can walk back.",py:"Méi chē dàbuliǎo zǒu huiqu."},{zh:"这个工作不合适，大不了换一个。",en:"If this job does not suit me, I can always change it.",py:"Zhège gōngzuò bù héshì, dàbuliǎo huàn yí ge."}],exercises:[{q:"填空：失败了___再试一次。",a:"大不了",instr:"填空",instrEn:"Fill in the blank",body:"失败了___再试一次。"},{q:"翻译：At worst, we can walk back.",a:"大不了走回去。",instr:"翻译",instrEn:"Translate",body:"At worst, we can walk back."},{q:"用“大不了”表达：不合适就换一个。",a:"不合适，大不了换一个。"}],note:"用于把最坏情况说出来，常有安慰、看得开的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dàbuliǎo + worst outcome = at worst … / the worst that can happen is …",noteEn:'Names the worst case, often in a reassuring, "no big deal" tone.',typeEn:"Set phrase"}]},{num:7,title:"我的人生我做主",points:[{id:"HSK6.07.1",name:"介词“于”",pinyin:"yú",type:"介词",explainEn:"于 is a formal preposition that can mean “at/in/to/from/than”, depending on context.",structure:"动词/形容词 + 于 + 人/地/时间/比较对象",examples:[{zh:"会议将于九点开始。",en:"The meeting will begin at nine.",py:"Huìyì jiāng yú jiǔ diǎn kāishǐ."},{zh:"这本书出版于去年。",en:"This book was published last year.",py:"Zhè běn shū chūbǎn yú qùnián."},{zh:"他的成绩高于平均水平。",en:"His score is above the average.",py:"Tā de chéngjì gāo yú píngjūn shuǐpíng."}],exercises:[{q:"填空：会议将___九点开始。",a:"于",instr:"填空",instrEn:"Fill in the blank",body:"会议将___九点开始。"},{q:"翻译：His score is above the average.",a:"他的成绩高于平均水平。",instr:"翻译",instrEn:"Translate",body:"His score is above the average."},{q:"把“在去年出版”改成较正式的表达。",a:"出版于去年"}],note:"“于”书面语色彩强，具体意义要根据搭配判断。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Verb/Adj + yú + person/place/time/compared item = at / in / to / from / than …",noteEn:"于 is strongly formal; its exact meaning depends on what it goes with.",typeEn:"Preposition"},{id:"HSK6.07.2",name:"动词/连词“致使”",pinyin:"zhìshǐ",type:"动词/连词",explainEn:"Use 致使 to mean “cause / lead to”, usually for a negative result.",structure:"原因 + 致使 + 不良结果",examples:[{zh:"大雨致使比赛取消。",en:"Heavy rain caused the game to be canceled.",py:"Dàyǔ zhìshǐ bǐsài qǔxiāo."},{zh:"操作错误致使系统停止工作。",en:"An operating error caused the system to stop working.",py:"Cāozuò cuòwù zhìshǐ xìtǒng tíngzhǐ gōngzuò."},{zh:"长期缺少睡眠可能致使身体出现问题。",en:"Long-term lack of sleep may lead to health problems.",py:"Chángqī quēshǎo shuìmián kěnéng zhìshǐ shēntǐ chūxiàn wèntí."}],exercises:[{q:"填空：大雨___比赛取消。",a:"致使",instr:"填空",instrEn:"Fill in the blank",body:"大雨___比赛取消。"},{q:"翻译：The error caused the system to stop.",a:"操作错误致使系统停止工作。",instr:"翻译",instrEn:"Translate",body:"The error caused the system to stop."},{q:"选择：多用于不良结果的“cause”，用（致使 / 便于）。",a:"致使",instr:"选择",instrEn:"Choose",body:"多用于不良结果的“cause”，用（致使 / 便于）。"}],note:"较正式，后面的结果往往是不希望发生的。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Cause + zhìshǐ + bad result = … causes / leads to …",noteEn:"Fairly formal; the result that follows is usually unwanted.",typeEn:"Verb / Conjunction"},{id:"HSK6.07.3",name:"“并非”表示否定判断",pinyin:"bìngfēi",type:"否定结构",explainEn:"Use 并非 to mean “is not actually / not necessarily”.",structure:"并非 + 名词/形容词/小句",examples:[{zh:"事情并非你想的那么简单。",en:"The matter is not actually as simple as you think.",py:"Shìqing bìngfēi nǐ xiǎng de nàme jiǎndān."},{zh:"成功并非完全靠运气。",en:"Success does not depend entirely on luck.",py:"Chénggōng bìngfēi wánquán kào yùnqi."},{zh:"他并非不愿意，只是没有时间。",en:"It is not that he is unwilling; he just has no time.",py:"Tā bìngfēi bú yuànyì, zhǐshì méiyǒu shíjiān."}],exercises:[{q:"填空：事情___那么简单。",a:"并非",instr:"填空",instrEn:"Fill in the blank",body:"事情___那么简单。"},{q:"翻译：Success does not depend entirely on luck.",a:"成功并非完全靠运气。",instr:"翻译",instrEn:"Translate",body:"Success does not depend entirely on luck."},{q:"用“并非”改写：他不是不愿意。",a:"他并非不愿意。"}],note:"比“不是”更正式，常用于纠正判断或部分否定。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bìngfēi + Noun/Adj/Clause = it is not (actually) …",noteEn:"More formal than 不是; often corrects a judgment or gives a partial negation.",typeEn:"Negation"}]},{num:8,title:"遇见原来的我",points:[{id:"HSK6.08.1",name:"固定格式“对……而言”",pinyin:"duì ... ér yán",type:"固定格式",explainEn:"Use 对…而言 to mean “for… / from the point of view of…”. It is formal.",structure:"对 + 人/事物 + 而言，……",examples:[{zh:"对我而言，健康最重要。",en:"For me, health is the most important.",py:"Duì wǒ ér yán, jiànkāng zuì zhòngyào."},{zh:"对初学者而言，这篇文章有点儿难。",en:"For beginners, this article is a little difficult.",py:"Duì chūxuézhě ér yán, zhè piān wénzhāng yǒudiǎnr nán."},{zh:"对公司而言，信誉非常重要。",en:"For a company, reputation is very important.",py:"Duì gōngsī ér yán, xìnyù fēicháng zhòngyào."}],exercises:[{q:"填空：___我___，健康最重要。",a:"对；而言",instr:"填空",instrEn:"Fill in the blank",body:"___我___，健康最重要。"},{q:"翻译：For beginners, this article is difficult.",a:"对初学者而言，这篇文章有点儿难。",instr:"翻译",instrEn:"Translate",body:"For beginners, this article is difficult."},{q:"用“对……而言”表达：对公司来说，信誉很重要。",a:"对公司而言，信誉很重要。"}],note:"与“对……来说”接近，但更书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"duì + person/thing + ér yán, … = for … / as far as … is concerned",noteEn:"Close to 对……来说, but more formal.",typeEn:"Fixed pattern"},{id:"HSK6.08.2",name:"“有关”表示相关/关于",pinyin:"yǒuguān",type:"动词/介词",explainEn:"Use 有关 to mean “related to / concerning”.",structure:"与 + N + 有关；有关 + N",examples:[{zh:"这个问题与安全有关。",en:"This issue is related to safety.",py:"Zhège wèntí yǔ ānquán yǒuguān."},{zh:"我想了解有关申请的规定。",en:"I want to learn about the rules concerning the application.",py:"Wǒ xiǎng liǎojiě yǒuguān shēnqǐng de guīdìng."},{zh:"有关情况我们以后再讨论。",en:"We will discuss the relevant situation later.",py:"Yǒuguān qíngkuàng wǒmen yǐhòu zài tǎolùn."}],exercises:[{q:"填空：这件事___安全有关。",a:"与",instr:"填空",instrEn:"Fill in the blank",body:"这件事___安全有关。"},{q:"翻译：rules concerning the application",a:"有关申请的规定",instr:"翻译",instrEn:"Translate",body:"rules concerning the application"},{q:"选择：表示“related to”用（有关 / 所在）。",a:"有关",instr:"选择",instrEn:"Choose",body:"表示“related to”用（有关 / 所在）。"}],note:"可作动词“与……有关”，也可直接修饰名词“有关规定”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yǔ + N + yǒuguān; yǒuguān + N = related to N; N concerned",noteEn:"Works as a verb (与……有关) or directly before a noun (有关规定).",typeEn:"Verb / Preposition"},{id:"HSK6.08.3",name:"插入语“不瞒你说”",pinyin:"bùmán nǐ shuō",type:"插入语",explainEn:"Use 不瞒你说 before saying something honestly or privately: “to tell you the truth”.",structure:"不瞒你说，+ 真心话/真实情况",examples:[{zh:"不瞒你说，我也有点儿紧张。",en:"To tell you the truth, I am a little nervous too.",py:"Bù mán nǐ shuō, wǒ yě yǒudiǎnr jǐnzhāng."},{zh:"不瞒你说，我以前想过放弃。",en:"To be honest, I once thought about giving up.",py:"Bù mán nǐ shuō, wǒ yǐqián xiǎngguo fàngqì."},{zh:"不瞒你说，这个决定我考虑了很久。",en:"To tell you the truth, I thought about this decision for a long time.",py:"Bù mán nǐ shuō, zhège juédìng wǒ kǎolǜle hěn jiǔ."}],exercises:[{q:"填空：___，我也有点儿担心。",a:"不瞒你说",instr:"填空",instrEn:"Fill in the blank",body:"___，我也有点儿担心。"},{q:"翻译：To tell you the truth, I once thought about giving up.",a:"不瞒你说，我以前想过放弃。",instr:"翻译",instrEn:"Translate",body:"To tell you the truth, I once thought about giving up."},{q:"选择：说真实想法前可用（不瞒你说 / 归根到底）。",a:"不瞒你说",instr:"选择",instrEn:"Choose",body:"说真实想法前可用（不瞒你说 / 归根到底）。"}],note:"常用于口语，引出比较真诚、私人的内容。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bù mán nǐ shuō, + honest words / the real situation = to tell you the truth, …",noteEn:"Common in speech; introduces something sincere or personal.",typeEn:"Parenthetical"}]},{num:9,title:"不用手机的日子",points:[{id:"HSK6.09.1",name:"状态形容词“通红、雪白”等",pinyin:"tōnghóng, xuěbái děng",type:"状态形容词",explainEn:"Some fixed forms use a noun/adverb-like element to strongly describe color or state.",structure:"通/雪/冰/笔 + 单音节形容词",examples:[{zh:"她跑得脸通红。",en:"Her face turned bright red from running.",py:"Tā pǎo de liǎn tōnghóng."},{zh:"山顶的雪雪白雪白的。",en:"The snow on the mountaintop is pure white.",py:"Shāndǐng de xuě xuěbái xuěbái de."},{zh:"她穿着一件雪白的衬衫。",en:"She is wearing a snow-white shirt.",py:"Tā chuānzhe yí jiàn xuěbái de chènshān."}],exercises:[{q:"填空：他一紧张，脸就___。",a:"通红",instr:"填空",instrEn:"Fill in the blank",body:"他一紧张，脸就___。"},{q:"翻译：She is wearing a snow-white shirt.",a:"她穿着一件雪白的衬衫。",instr:"翻译",instrEn:"Translate",body:"She is wearing a snow-white shirt."},{q:"选择：表示“bright red”用（通红 / 雪白）。",a:"通红",instr:"选择",instrEn:"Choose",body:"表示“bright red”用（通红 / 雪白）。"}],note:"这类词强调状态很鲜明，很多是固定搭配，需要整体记忆。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"tōng/xuě/bīng/bǐ + one-syllable Adj = vividly … (bright red, snow-white, …)",noteEn:"These words paint a vivid state; many are set combinations best learned as whole words.",typeEn:"Vivid adjective"},{id:"HSK6.09.2",name:"固定格式“说A就A”",pinyin:"shuō A jiù A",type:"固定格式",explainEn:"Use 说A就A to show someone acts immediately once they decide or say it.",structure:"说 + 动词 + 就 + 同一动词",examples:[{zh:"他说走就走，一点儿也不犹豫。",en:"He left as soon as he decided to leave, without hesitation.",py:"Tā shuō zǒu jiù zǒu, yìdiǎnr yě bù yóuyù."},{zh:"她说做就做，当天就开始准备。",en:"She started as soon as she said she would.",py:"Tā shuō zuò jiù zuò, dàngtiān jiù kāishǐ zhǔnbèi."},{zh:"这个人说来就来，说走就走。",en:"This person comes and goes whenever he decides.",py:"Zhège rén shuō lái jiù lái, shuō zǒu jiù zǒu."}],exercises:[{q:"填空：他说走___走。",a:"就",instr:"填空",instrEn:"Fill in the blank",body:"他说走___走。"},{q:"翻译：She started as soon as she decided.",a:"她说做就做。",instr:"翻译",instrEn:"Translate",body:"She started as soon as she decided."},{q:"用该格式表达：他说去就马上去。",a:"他说去就去。"}],note:"强调动作干脆、立即发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"shuō + Verb + jiù + same Verb = do it the moment you say so",noteEn:"Stresses that the action is done decisively and at once.",typeEn:"Fixed pattern"},{id:"HSK6.09.3",name:"“形容词/动词 + 得要命”",pinyin:"xíngróngcí/dòngcí + de yàomìng",type:"程度补语",explainEn:"Use 得要命 after an adjective or feeling/state verb to mean “extremely”.",structure:"形容词/状态动词 + 得要命",examples:[{zh:"今天热得要命。",en:"It is extremely hot today.",py:"Jīntiān rè de yàomìng."},{zh:"我困得要命。",en:"I am terribly sleepy.",py:"Wǒ kùn de yàomìng."},{zh:"他紧张得要命。",en:"He is extremely nervous.",py:"Tā jǐnzhāng de yàomìng."}],exercises:[{q:"填空：今天热___。",a:"得要命",instr:"填空",instrEn:"Fill in the blank",body:"今天热___。"},{q:"翻译：I am terribly sleepy.",a:"我困得要命。",instr:"翻译",instrEn:"Translate",body:"I am terribly sleepy."},{q:"用“得要命”改写：他非常紧张。",a:"他紧张得要命。"}],note:"口语较强烈，常表达不舒服、紧张、累、热等状态。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Adj / state verb + de yàomìng = terribly … / extremely …",noteEn:"Strongly colloquial; often describes discomfort, nerves, tiredness, heat, etc.",typeEn:"Degree complement"}]},{num:10,title:"全球化视野中的中国饮食",points:[{id:"HSK6.10.1",name:"连词“以至”",pinyin:"yǐzhì",type:"连词",explainEn:"Use 以至 to introduce a result that develops from the previous situation: “so that / to the extent that”.",structure:"原因/发展 + 以至 + 结果",examples:[{zh:"他太专心了，以至忘了吃饭。",en:"He was so focused that he forgot to eat.",py:"Tā tài zhuānxīn le, yǐzhì wàngle chīfàn."},{zh:"道路结冰，以至很多车无法通行。",en:"The road froze, so many cars could not pass.",py:"Dàolù jiébīng, yǐzhì hěn duō chē wúfǎ tōngxíng."},{zh:"他长期熬夜，以至身体越来越差。",en:"He stayed up late for a long time, so his health became worse.",py:"Tā chángqī áoyè, yǐzhì shēntǐ yuèláiyuè chà."}],exercises:[{q:"填空：他太专心了，___忘了吃饭。",a:"以至",instr:"填空",instrEn:"Fill in the blank",body:"他太专心了，___忘了吃饭。"},{q:"翻译：The road froze, so many cars could not pass.",a:"道路结冰，以至很多车无法通行。",instr:"翻译",instrEn:"Translate",body:"The road froze, so many cars could not pass."},{q:"连接：长期熬夜。身体越来越差。（用“以至”）",a:"他长期熬夜，以至身体越来越差。",instr:"连接",instrEn:"Join the sentences",body:"长期熬夜。身体越来越差。（用“以至”）"}],note:"较书面，后面多是前一情况发展导致的结果。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Cause / development + yǐzhì + result = so much so that …",noteEn:"Fairly formal; what follows is usually a result that grew out of the previous situation.",typeEn:"Conjunction"},{id:"HSK6.10.2",name:"连词“即便”",pinyin:"jíbiàn",type:"连词",explainEn:"Use 即便 to mean “even if / even though”.",structure:"即便 + 条件，也/还 + 结果",examples:[{zh:"即便下雨，我们也会按时出发。",en:"Even if it rains, we will leave on time.",py:"Jíbiàn xià yǔ, wǒmen yě huì ànshí chūfā."},{zh:"即便失败了，也不要放弃。",en:"Even if you fail, do not give up.",py:"Jíbiàn shībài le, yě búyào fàngqì."},{zh:"即便很忙，他还是坚持读书。",en:"Even though he is busy, he still keeps reading.",py:"Jíbiàn hěn máng, tā háishi jiānchí dúshū."}],exercises:[{q:"填空：___失败，也不要放弃。",a:"即便",instr:"填空",instrEn:"Fill in the blank",body:"___失败，也不要放弃。"},{q:"翻译：Even if it rains, we will leave on time.",a:"即便下雨，我们也会按时出发。",instr:"翻译",instrEn:"Translate",body:"Even if it rains, we will leave on time."},{q:"选择：表示“even if”较书面，用（即便 / 顿时）。",a:"即便",instr:"选择",instrEn:"Choose",body:"表示“even if”较书面，用（即便 / 顿时）。"}],note:"和“即使”接近，书面语较常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jíbiàn + condition, yě/hái + result = even if …, still …",noteEn:"Close to 即使; more common in writing.",typeEn:"Conjunction"},{id:"HSK6.10.3",name:"名词“所在”",pinyin:"suǒzài",type:"名词",explainEn:"Use 所在 to mean “the place/key point where something lies”.",structure:"问题/原因/意义 + 所在；所在地",examples:[{zh:"这正是问题所在。",en:"This is exactly where the problem lies.",py:"Zhè zhèng shì wèntí suǒzài."},{zh:"我们终于找到了原因所在。",en:"We finally found where the cause lies.",py:"Wǒmen zhōngyú zhǎodàole yuányīn suǒzài."},{zh:"请填写公司所在地。",en:"Please fill in the location of the company.",py:"Qǐng tiánxiě gōngsī suǒzàidì."}],exercises:[{q:"填空：这正是问题___。",a:"所在",instr:"填空",instrEn:"Fill in the blank",body:"这正是问题___。"},{q:"翻译：We found where the cause lies.",a:"我们找到了原因所在。",instr:"翻译",instrEn:"Translate",body:"We found where the cause lies."},{q:"选择：company location = 公司（所在 / 所在地）。",a:"所在地",instr:"选择",instrEn:"Choose",body:"company location = 公司（所在 / 所在地）。"}],note:"常见“问题所在、原因所在、意义所在、所在地”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wèntí/yuányīn/yìyì + suǒzài; suǒzàidì = where the problem/reason/meaning lies; location",noteEn:"Common in 问题所在, 原因所在, 意义所在, 所在地.",typeEn:"Noun"}]},{num:11,title:"我不在时，猫在干什么",points:[{id:"HSK6.11.1",name:"副词“统统”",pinyin:"tǒngtǒng",type:"副词",explainEn:"Use 统统 to mean “all / entirely”, with strong emphasis.",structure:"范围 + 统统 + 谓语",examples:[{zh:"这些问题我统统解决了。",en:"I solved all these problems.",py:"Zhèxiē wèntí wǒ tǒngtǒng jiějué le."},{zh:"他把旧东西统统扔掉了。",en:"He threw all the old things away.",py:"Tā bǎ jiù dōngxi tǒngtǒng rēngdiào le."},{zh:"不需要的文件统统删除。",en:"Delete all unnecessary files.",py:"Bù xūyào de wénjiàn tǒngtǒng shānchú."}],exercises:[{q:"填空：这些问题我___解决了。",a:"统统",instr:"填空",instrEn:"Fill in the blank",body:"这些问题我___解决了。"},{q:"翻译：He threw all the old things away.",a:"他把旧东西统统扔掉了。",instr:"翻译",instrEn:"Translate",body:"He threw all the old things away."},{q:"选择：强调“all”用（统统 / 偶尔）。",a:"统统",instr:"选择",instrEn:"Choose",body:"强调“all”用（统统 / 偶尔）。"}],note:"比“都”语气更强，常表示一个不剩。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Scope + tǒngtǒng + predicate = all of it / every last one",noteEn:'Stronger than 都; often means "every last one".',typeEn:"Adverb"},{id:"HSK6.11.2",name:"固定格式“以……为……”",pinyin:"yǐ ... wéi ...",type:"固定格式",explainEn:"Use 以…为… to mean “take/use…as…”. It is formal.",structure:"以 + A + 为 + B",examples:[{zh:"我们以安全为第一原则。",en:"We take safety as our first principle.",py:"Wǒmen yǐ ānquán wéi dì-yī yuánzé."},{zh:"这家公司以服务好而闻名。",en:"This company is famous for good service.",py:"Zhè jiā gōngsī yǐ fúwù hǎo ér wénmíng."},{zh:"文章以一个真实故事为例。",en:"The article uses a true story as an example.",py:"Wénzhāng yǐ yí ge zhēnshí gùshi wéi lì."}],exercises:[{q:"填空：我们___安全___第一原则。",a:"以；为",instr:"填空",instrEn:"Fill in the blank",body:"我们___安全___第一原则。"},{q:"翻译：The article uses a true story as an example.",a:"文章以一个真实故事为例。",instr:"翻译",instrEn:"Translate",body:"The article uses a true story as an example."},{q:"用“以……为……”表达：把北京作为起点。",a:"以北京为起点"}],note:"常见“以……为主、以……为例、以……为目标、以……为基础”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yǐ + A + wéi + B = take A as B",noteEn:"Common in 以……为主, 以……为例, 以……为目标, 以……为基础.",typeEn:"Fixed pattern"},{id:"HSK6.11.3",name:"固定格式“该干吗干吗”",pinyin:"gāi gànmá gànmá",type:"固定格式",explainEn:"Use 该干吗干吗 to mean “just do whatever you normally should do”.",structure:"该 + 动词/动宾 + 什么/吗 + 动词/动宾",examples:[{zh:"你别管我，该干吗干吗。",en:"Do not worry about me; just do what you normally do.",py:"Nǐ bié guǎn wǒ, gāi gànmá gànmá."},{zh:"放假也不用特别安排，该干吗干吗。",en:"You do not need special plans for the holiday; just do as usual.",py:"Fàngjià yě búyòng tèbié ānpái, gāi gànmá gànmá."},{zh:"医生说没事，让我该吃吃，该睡睡。",en:"The doctor said I was fine and told me to eat and sleep as usual.",py:"Yīshēng shuō méishì, ràng wǒ gāi chī chī, gāi shuì shuì."}],exercises:[{q:"填空：你别担心，___干吗干吗。",a:"该",instr:"填空",instrEn:"Fill in the blank",body:"你别担心，___干吗干吗。"},{q:"翻译：Just do as usual.",a:"该干吗干吗。",instr:"翻译",instrEn:"Translate",body:"Just do as usual."},{q:"补全：医生说我可以该吃___，该睡___。",a:"吃；睡",instr:"补全",instrEn:"Complete the sentence",body:"医生说我可以该吃___，该睡___。"}],note:"口语固定格式，表示不必因某事改变正常生活。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"gāi + Verb/V-O + shénme/má + Verb/V-O = just do whatever you'd normally do",noteEn:"A spoken set pattern: no need to change your normal life because of something.",typeEn:"Fixed pattern"}]},{num:12,title:"我们都爱白噪音",points:[{id:"HSK6.12.1",name:"副词“不妨”",pinyin:"bùfáng",type:"副词",explainEn:"Use 不妨 to make a mild suggestion: “you might as well / why not”.",structure:"不妨 + 动词",examples:[{zh:"累了不妨休息一会儿。",en:"If you are tired, you might as well rest for a while.",py:"Lèi le bùfáng xiūxi yíhuìr."},{zh:"这个办法不错，你不妨试试。",en:"This method is good; why not try it?",py:"Zhège bànfǎ búcuò, nǐ bùfáng shìshi."},{zh:"周末不妨出去走走。",en:"You might as well go out for a walk this weekend.",py:"Zhōumò bùfáng chūqu zǒuzou."}],exercises:[{q:"填空：这个办法你___试试。",a:"不妨",instr:"填空",instrEn:"Fill in the blank",body:"这个办法你___试试。"},{q:"翻译：You might as well rest for a while.",a:"你不妨休息一会儿。",instr:"翻译",instrEn:"Translate",body:"You might as well rest for a while."},{q:"选择：委婉建议用（不妨 / 务必）。",a:"不妨",instr:"选择",instrEn:"Choose",body:"委婉建议用（不妨 / 务必）。"}],note:"语气比“应该、必须”轻，常用于建议。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùfáng + Verb = you might as well … / why not …",noteEn:"Softer than 应该/必须; used for suggestions.",typeEn:"Adverb"},{id:"HSK6.12.2",name:"副词“务必”",pinyin:"wùbì",type:"副词",explainEn:"Use 务必 to mean “must / be sure to”. It is formal and strong.",structure:"务必 + 动词",examples:[{zh:"请务必按时到达。",en:"Please be sure to arrive on time.",py:"Qǐng wùbì ànshí dàodá."},{zh:"出门前务必关好门窗。",en:"Be sure to close the doors and windows before leaving.",py:"Chūmén qián wùbì guānhǎo ménchuāng."},{zh:"重要文件务必备份。",en:"Important files must be backed up.",py:"Zhòngyào wénjiàn wùbì bèifèn."}],exercises:[{q:"填空：请___按时到达。",a:"务必",instr:"填空",instrEn:"Fill in the blank",body:"请___按时到达。"},{q:"翻译：Be sure to close the doors and windows.",a:"出门前务必关好门窗。",instr:"翻译",instrEn:"Translate",body:"Be sure to close the doors and windows."},{q:"选择：强烈要求用（务必 / 不妨）。",a:"务必",instr:"选择",instrEn:"Choose",body:"强烈要求用（务必 / 不妨）。"}],note:"常见于通知、提醒、正式要求。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wùbì + Verb = be sure to … / must",noteEn:"Common in notices, reminders and formal requests.",typeEn:"Adverb"},{id:"HSK6.12.3",name:"连词“鉴于”",pinyin:"jiànyú",type:"连词/介词",explainEn:"Use 鉴于 to mean “in view of / considering”. It introduces a known reason.",structure:"鉴于 + 情况/原因，+ 决定/结果",examples:[{zh:"鉴于天气不好，活动改到室内。",en:"In view of the bad weather, the event was moved indoors.",py:"Jiànyú tiānqì bù hǎo, huódòng gǎidào shìnèi."},{zh:"鉴于时间有限，我们先讨论重点。",en:"Considering the limited time, let us discuss the key points first.",py:"Jiànyú shíjiān yǒuxiàn, wǒmen xiān tǎolùn zhòngdiǎn."},{zh:"鉴于他的表现，公司决定给他机会。",en:"In view of his performance, the company decided to give him a chance.",py:"Jiànyú tā de biǎoxiàn, gōngsī juédìng gěi tā jīhuì."}],exercises:[{q:"填空：___时间有限，我们先说重点。",a:"鉴于",instr:"填空",instrEn:"Fill in the blank",body:"___时间有限，我们先说重点。"},{q:"翻译：In view of the bad weather, the event was moved indoors.",a:"鉴于天气不好，活动改到室内。",instr:"翻译",instrEn:"Translate",body:"In view of the bad weather, the event was moved indoors."},{q:"用“鉴于”连接：情况特殊。会议延期。",a:"鉴于情况特殊，会议延期。"}],note:"较正式，常用于书面说明原因和决定。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jiànyú + situation/reason, + decision/result = in view of …, …",noteEn:"Fairly formal; used in writing to state a reason and the decision taken.",typeEn:"Conjunction / Prep."}]},{num:13,title:"从旅游指南看世事变迁",points:[{id:"HSK6.13.1",name:"动词“便于”",pinyin:"biànyú",type:"动词",explainEn:"Use 便于 to mean “be convenient for / make it easier to…”.",structure:"便于 + 动词/名词",examples:[{zh:"这个表格便于大家比较。",en:"This table makes comparison easier.",py:"Zhège biǎogé biànyú dàjiā bǐjiào."},{zh:"文件按日期分类，便于查找。",en:"The files are sorted by date for easier searching.",py:"Wénjiàn àn rìqī fēnlèi, biànyú cházhǎo."},{zh:"请留下电话，便于我们联系你。",en:"Please leave your phone number so we can contact you easily.",py:"Qǐng liúxià diànhuà, biànyú wǒmen liánxì nǐ."}],exercises:[{q:"填空：文件分类，___查找。",a:"便于",instr:"填空",instrEn:"Fill in the blank",body:"文件分类，___查找。"},{q:"翻译：This table makes comparison easier.",a:"这个表格便于大家比较。",instr:"翻译",instrEn:"Translate",body:"This table makes comparison easier."},{q:"选择：表示“make it easy to contact”用（便于联系 / 难以联系）。",a:"便于联系",instr:"选择",instrEn:"Choose",body:"表示“make it easy to contact”用（便于联系 / 难以联系）。"}],note:"常用于说明某种安排带来的便利。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"biànyú + Verb/Noun = make it easy to …",noteEn:"Often explains the convenience an arrangement brings.",typeEn:"Verb"},{id:"HSK6.13.2",name:"动词“犹如”",pinyin:"yóurú",type:"动词/比喻词",explainEn:"Use 犹如 to mean “be like / just like”. It is literary/formal.",structure:"A + 犹如 + B",examples:[{zh:"平静的湖面犹如一面镜子。",en:"The calm lake is like a mirror.",py:"Píngjìng de húmiàn yóurú yí miàn jìngzi."},{zh:"孩子的笑声犹如阳光一样温暖。",en:"The child's laughter is as warm as sunshine.",py:"Háizi de xiàoshēng yóurú yángguāng yíyàng wēnnuǎn."},{zh:"网络犹如一座巨大的图书馆。",en:"The internet is like a huge library.",py:"Wǎngluò yóurú yí zuò jùdà de túshūguǎn."}],exercises:[{q:"填空：湖面___一面镜子。",a:"犹如",instr:"填空",instrEn:"Fill in the blank",body:"湖面___一面镜子。"},{q:"翻译：The internet is like a huge library.",a:"网络犹如一座巨大的图书馆。",instr:"翻译",instrEn:"Translate",body:"The internet is like a huge library."},{q:"用“犹如”改写：笑声像阳光一样温暖。",a:"笑声犹如阳光一样温暖。"}],note:"比“像”更书面，常用于比喻。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + yóurú + B = A is just like B",noteEn:"More literary than 像; used in similes.",typeEn:"Verb / Simile word"},{id:"HSK6.13.3",name:"比较格式“和……相比”",pinyin:"hé ... xiāngbǐ",type:"比较结构",explainEn:"Use 和…相比 to mean “compared with…”.",structure:"A + 和 + B + 相比，……",examples:[{zh:"和去年相比，今年更忙。",en:"Compared with last year, this year is busier.",py:"Hé qùnián xiāngbǐ, jīnnián gèng máng."},{zh:"和开车相比，坐地铁更方便。",en:"Compared with driving, taking the subway is more convenient.",py:"Hé kāichē xiāngbǐ, zuò dìtiě gèng fāngbiàn."},{zh:"和以前相比，他成熟多了。",en:"Compared with before, he is much more mature.",py:"Hé yǐqián xiāngbǐ, tā chéngshú duō le."}],exercises:[{q:"填空：___去年___，今年更忙。",a:"和；相比",instr:"填空",instrEn:"Fill in the blank",body:"___去年___，今年更忙。"},{q:"翻译：Compared with driving, the subway is more convenient.",a:"和开车相比，坐地铁更方便。",instr:"翻译",instrEn:"Translate",body:"Compared with driving, the subway is more convenient."},{q:"用“和……相比”表达：现在比以前方便。",a:"和以前相比，现在更方便。"}],note:"比较对象常放在前面，后句说明差异。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + hé + B + xiāngbǐ, … = compared with B, A …",noteEn:"The thing compared usually comes first; the next clause says how they differ.",typeEn:"Comparison structure"}]},{num:14,title:"背着电饭锅拍北极",points:[{id:"HSK6.14.1",name:"数量短语的重叠",pinyin:"shùliàng duǎnyǔ de chóngdié",type:"数量结构",explainEn:"Repeat a number-measure phrase to mean “one by one / in groups / gradually”.",structure:"一A一A；两A两A；数量短语重叠 + 地/都",examples:[{zh:"大家一个一个地进去。",en:"Everyone went in one by one.",py:"Dàjiā yí ge yí ge de jìnqu."},{zh:"请一页一页地看。",en:"Please read page by page.",py:"Qǐng yí yè yí yè de kàn."},{zh:"学生两个人两个人地练习。",en:"The students practice in pairs.",py:"Xuésheng liǎng ge rén liǎng ge rén de liànxí."}],exercises:[{q:"填空：大家一个___个地进去。",a:"一",instr:"填空",instrEn:"Fill in the blank",body:"大家一个___个地进去。"},{q:"翻译：Please read page by page.",a:"请一页一页地看。",instr:"翻译",instrEn:"Translate",body:"Please read page by page."},{q:"用数量重叠表达：学生两人一组练习。",a:"学生两个人两个人地练习。"}],note:"表示按相同数量依次、分组或逐步进行。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yī A yī A; liǎng A liǎng A; repeated num-measure + de/dōu = one by one / two by two",noteEn:"Means doing something in equal amounts, in turn, in groups or step by step.",typeEn:"Quantity structure"},{id:"HSK6.14.2",name:"动词“难以”",pinyin:"nányǐ",type:"动词",explainEn:"Use 难以 before a verb to mean “be difficult to / hard to”.",structure:"难以 + 动词",examples:[{zh:"这个问题难以解决。",en:"This problem is difficult to solve.",py:"Zhège wèntí nányǐ jiějué."},{zh:"他的心情难以用语言表达。",en:"His feelings are hard to express in words.",py:"Tā de xīnqíng nányǐ yòng yǔyán biǎodá."},{zh:"这个变化短期内难以看出来。",en:"This change is hard to see in the short term.",py:"Zhège biànhuà duǎnqī nèi nányǐ kàn chulai."}],exercises:[{q:"填空：这个问题___解决。",a:"难以",instr:"填空",instrEn:"Fill in the blank",body:"这个问题___解决。"},{q:"翻译：His feelings are hard to express.",a:"他的心情难以表达。",instr:"翻译",instrEn:"Translate",body:"His feelings are hard to express."},{q:"选择：表示“hard to understand”用（难以理解 / 便于理解）。",a:"难以理解",instr:"选择",instrEn:"Choose",body:"表示“hard to understand”用（难以理解 / 便于理解）。"}],note:"较书面，后面直接接动词。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nányǐ + Verb = hard to …",noteEn:"Fairly formal; followed directly by a verb.",typeEn:"Verb"},{id:"HSK6.14.3",name:"连词“免得”",pinyin:"miǎnde",type:"连词",explainEn:"Use 免得 to mean “so as to avoid / lest”.",structure:"动作1，免得 + 不好的结果",examples:[{zh:"早点儿出发，免得堵车。",en:"Leave early to avoid traffic.",py:"Zǎo diǎnr chūfā, miǎnde dǔchē."},{zh:"把地址记下来，免得忘了。",en:"Write down the address so you do not forget it.",py:"Bǎ dìzhǐ jì xialai, miǎnde wàng le."},{zh:"多带一件衣服，免得晚上冷。",en:"Bring an extra piece of clothing in case it gets cold at night.",py:"Duō dài yí jiàn yīfu, miǎnde wǎnshang lěng."}],exercises:[{q:"填空：早点儿出发，___堵车。",a:"免得",instr:"填空",instrEn:"Fill in the blank",body:"早点儿出发，___堵车。"},{q:"翻译：Write down the address so you do not forget it.",a:"把地址记下来，免得忘了。",instr:"翻译",instrEn:"Translate",body:"Write down the address so you do not forget it."},{q:"连接：带伞。避免下雨时淋湿。（用“免得”）",a:"带把伞，免得下雨时淋湿。",instr:"连接",instrEn:"Join the sentences",body:"带伞。避免下雨时淋湿。（用“免得”）"}],note:"后面通常是不希望发生的结果。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Action 1, miǎnde + bad result = so as not to … / lest …",noteEn:"What follows is usually an unwanted result.",typeEn:"Conjunction"}]},{num:15,title:"山脉上的雕刻",points:[{id:"HSK6.15.1",name:"副词“时而”",pinyin:"shí’ér",type:"副词",explainEn:"Use 时而 to mean “from time to time / sometimes”, often with changing states.",structure:"时而 + A，时而 + B",examples:[{zh:"天气时而晴，时而下雨。",en:"The weather is sunny at times and rainy at times.",py:"Tiānqì shí'ér qíng, shí'ér xià yǔ."},{zh:"他时而认真，时而开玩笑。",en:"Sometimes he is serious, sometimes he jokes.",py:"Tā shí'ér rènzhēn, shí'ér kāi wánxiào."},{zh:"音乐时而轻柔，时而激烈。",en:"The music is sometimes soft and sometimes intense.",py:"Yīnyuè shí'ér qīngróu, shí'ér jīliè."}],exercises:[{q:"填空：天气___晴，___下雨。",a:"时而；时而",instr:"填空",instrEn:"Fill in the blank",body:"天气___晴，___下雨。"},{q:"翻译：The music is sometimes soft and sometimes intense.",a:"音乐时而轻柔，时而激烈。",instr:"翻译",instrEn:"Translate",body:"The music is sometimes soft and sometimes intense."},{q:"用“时而”表达两个交替状态。",a:"他时而认真，时而开玩笑。"}],note:"常用于两个或多个状态交替出现，书面感较强。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"shí'ér + A, shí'ér + B = now A, now B",noteEn:"Used when two or more states keep alternating; fairly literary.",typeEn:"Adverb"},{id:"HSK6.15.2",name:"副词“不禁”",pinyin:"bùjīn",type:"副词",explainEn:"Use 不禁 to mean “cannot help / involuntarily”.",structure:"不禁 + 动词",examples:[{zh:"看到这张照片，我不禁笑了。",en:"Seeing this photo, I could not help laughing.",py:"Kàndào zhè zhāng zhàopiàn, wǒ bùjīn xiào le."},{zh:"听到这个消息，她不禁流下眼泪。",en:"Hearing the news, she could not help crying.",py:"Tīngdào zhège xiāoxi, tā bùjīn liúxià yǎnlèi."},{zh:"看到家乡的变化，我不禁感到惊讶。",en:"Seeing the changes in my hometown, I could not help feeling surprised.",py:"Kàndào jiāxiāng de biànhuà, wǒ bùjīn gǎndào jīngyà."}],exercises:[{q:"填空：看到照片，我___笑了。",a:"不禁",instr:"填空",instrEn:"Fill in the blank",body:"看到照片，我___笑了。"},{q:"翻译：She could not help crying.",a:"她不禁流下眼泪。",instr:"翻译",instrEn:"Translate",body:"She could not help crying."},{q:"选择：表示自然产生反应用（不禁 / 预先）。",a:"不禁",instr:"选择",instrEn:"Choose",body:"表示自然产生反应用（不禁 / 预先）。"}],note:"和“不由得”接近，较书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùjīn + Verb = can't help … / involuntarily …",noteEn:"Close to 不由得; more formal.",typeEn:"Adverb"},{id:"HSK6.15.3",name:"副词“无不”",pinyin:"wúbù",type:"副词",explainEn:"Use 无不 to mean “without exception / all…”.",structure:"范围 + 无不 + 谓语",examples:[{zh:"听到这个消息，大家无不高兴。",en:"Everyone was happy to hear the news.",py:"Tīngdào zhège xiāoxi, dàjiā wúbù gāoxìng."},{zh:"来过这里的人无不喜欢这里的风景。",en:"Everyone who has been here likes the scenery.",py:"Láiguo zhèlǐ de rén wúbù xǐhuan zhèlǐ de fēngjǐng."},{zh:"观众无不为他的表现鼓掌。",en:"Every audience member applauded his performance.",py:"Guānzhòng wúbù wèi tā de biǎoxiàn gǔzhǎng."}],exercises:[{q:"填空：大家___高兴。",a:"无不",instr:"填空",instrEn:"Fill in the blank",body:"大家___高兴。"},{q:"翻译：Everyone who has been here likes the scenery.",a:"来过这里的人无不喜欢这里的风景。",instr:"翻译",instrEn:"Translate",body:"Everyone who has been here likes the scenery."},{q:"改写“所有观众都鼓掌”为“无不”句。",a:"观众无不鼓掌。"}],note:"“无不”相当于“没有一个不……”，书面语常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Scope + wúbù + predicate = all … without exception",noteEn:`无不 means "there is none that doesn't…"; common in writing.`,typeEn:"Adverb"}]},{num:16,title:"徐健和他的野生动物摄影师们",points:[{id:"HSK6.16.1",name:"插入语“换句话说”",pinyin:"huàn jù huà shuō",type:"插入语",explainEn:"Use 换句话说 to restate an idea more clearly: “in other words”.",structure:"前句，换句话说，+ 另一种解释",examples:[{zh:"他没有拒绝，换句话说，他可能同意了。",en:"He did not refuse; in other words, he may have agreed.",py:"Tā méiyǒu jùjué, huàn jù huà shuō, tā kěnéng tóngyì le."},{zh:"成本下降了，换句话说，我们可以卖得更便宜。",en:"Costs fell; in other words, we can sell more cheaply.",py:"Chéngběn xiàjiàng le, huàn jù huà shuō, wǒmen kěyǐ mài de gèng piányi."},{zh:"这个办法风险很小，换句话说，比较安全。",en:"This method has little risk; in other words, it is relatively safe.",py:"Zhège bànfǎ fēngxiǎn hěn xiǎo, huàn jù huà shuō, bǐjiào ānquán."}],exercises:[{q:"填空：成本下降了，___，价格可以降低。",a:"换句话说",instr:"填空",instrEn:"Fill in the blank",body:"成本下降了，___，价格可以降低。"},{q:"翻译：In other words, it is relatively safe.",a:"换句话说，它比较安全。",instr:"翻译",instrEn:"Translate",body:"In other words, it is relatively safe."},{q:"用“换句话说”重新解释：他可能同意了。",a:"他没有拒绝，换句话说，他可能同意了。"}],note:"用于解释、总结或用更容易理解的话重说前面内容。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Previous point, huàn jù huà shuō, + another way of putting it = in other words, …",noteEn:"Used to explain, sum up, or restate the previous point in easier words.",typeEn:"Parenthetical"},{id:"HSK6.16.2",name:"被动句“为……所……”",pinyin:"wéi ... suǒ ...",type:"被动句",explainEn:"Use 为…所… as a formal passive structure: “be…by…”.",structure:"受事 + 为 + 动作者 + 所 + 动词",examples:[{zh:"这个故事为很多人所熟悉。",en:"This story is familiar to many people.",py:"Zhège gùshi wéi hěn duō rén suǒ shúxī."},{zh:"他的作品为读者所喜爱。",en:"His works are loved by readers.",py:"Tā de zuòpǐn wéi dúzhě suǒ xǐ'ài."},{zh:"这种方法已为大家所接受。",en:"This method has been accepted by everyone.",py:"Zhè zhǒng fāngfǎ yǐ wéi dàjiā suǒ jiēshòu."}],exercises:[{q:"填空：这个故事___很多人___熟悉。",a:"为；所",instr:"填空",instrEn:"Fill in the blank",body:"这个故事___很多人___熟悉。"},{q:"翻译：His works are loved by readers.",a:"他的作品为读者所喜爱。",instr:"翻译",instrEn:"Translate",body:"His works are loved by readers."},{q:"把“大家接受了这种方法”改成“为……所……”句。",a:"这种方法为大家所接受。"}],note:"非常书面，多用于正式文章。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Receiver + wéi + doer + suǒ + Verb = be …-ed by … (formal passive)",noteEn:"Very formal; mostly in formal writing.",typeEn:"Passive"},{id:"HSK6.16.3",name:"动词“足以”",pinyin:"zúyǐ",type:"动词",explainEn:"Use 足以 to mean “be enough to / be sufficient to”.",structure:"足以 + 动词",examples:[{zh:"这些证据足以说明问题。",en:"This evidence is enough to explain the problem.",py:"Zhèxiē zhèngjù zúyǐ shuōmíng wèntí."},{zh:"一次失败不足以证明你不行。",en:"One failure is not enough to prove you cannot do it.",py:"Yí cì shībài bùzúyǐ zhèngmíng nǐ bù xíng."},{zh:"这段时间足以完成任务。",en:"This amount of time is enough to complete the task.",py:"Zhè duàn shíjiān zúyǐ wánchéng rènwu."}],exercises:[{q:"填空：这些证据___说明问题。",a:"足以",instr:"填空",instrEn:"Fill in the blank",body:"这些证据___说明问题。"},{q:"翻译：One failure is not enough to prove you cannot do it.",a:"一次失败不足以证明你不行。",instr:"翻译",instrEn:"Translate",body:"One failure is not enough to prove you cannot do it."},{q:"选择：表示“enough to finish”用（足以完成 / 难以完成）。",a:"足以完成",instr:"选择",instrEn:"Choose",body:"表示“enough to finish”用（足以完成 / 难以完成）。"}],note:"常见“足以/不足以 + 动词”，较书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zúyǐ + Verb = be enough to …",noteEn:"Common as 足以 / 不足以 + verb; fairly formal.",typeEn:"Verb"}]},{num:17,title:"小动物眼中的慢世界",points:[{id:"HSK6.17.1",name:"固定格式“东A西B”",pinyin:"dōng A xī B",type:"固定格式",explainEn:"Use 东A西B to mean doing similar actions here and there in different directions.",structure:"东 + 动词A + 西 + 动词B",examples:[{zh:"他在房间里东找西找，还是没找到钥匙。",en:"He searched here and there in the room but still did not find the key.",py:"Tā zài fángjiān li dōng zhǎo xī zhǎo, háishi méi zhǎodào yàoshi."},{zh:"孩子们东跑西跑，一刻也不停。",en:"The children ran here and there without stopping.",py:"Háizimen dōng pǎo xī pǎo, yíkè yě bù tíng."},{zh:"她买东西时总爱东挑西选。",en:"She always picks and chooses when shopping.",py:"Tā mǎi dōngxi shí zǒng ài dōng tiāo xī xuǎn."}],exercises:[{q:"填空：他在房间里东找___找。",a:"西",instr:"填空",instrEn:"Fill in the blank",body:"他在房间里东找___找。"},{q:"翻译：The children ran here and there.",a:"孩子们东跑西跑。",instr:"翻译",instrEn:"Translate",body:"The children ran here and there."},{q:"写一个“东A西B”结构表示到处看。",a:"东看西看"}],note:"A、B通常意义相近，表达动作反复、方向不定。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dōng + Verb A + xī + Verb B = A here, B there (all over the place)",noteEn:"A and B are usually similar in meaning; shows repeated actions in no fixed direction.",typeEn:"Fixed pattern"},{id:"HSK6.17.2",name:"动词“中（zhòng）”",pinyin:"zhòng",type:"动词",explainEn:"中 (zhòng) means “hit / be affected / win”, as in 中奖、中暑、中毒.",structure:"中 + 宾语/固定词",examples:[{zh:"他买了一张彩票，没想到中奖了。",en:"He bought a lottery ticket and unexpectedly won.",py:"Tā mǎile yì zhāng cǎipiào, méi xiǎngdào zhòngjiǎng le."},{zh:"天气太热，小心中暑。",en:"It is very hot; be careful not to get heatstroke.",py:"Tiānqì tài rè, xiǎoxīn zhòngshǔ."},{zh:"这些食物可能让人中毒。",en:"This food may cause poisoning.",py:"Zhèxiē shíwù kěnéng ràng rén zhòngdú."}],exercises:[{q:"填空：他买的彩票___奖了。",a:"中",instr:"填空",instrEn:"Fill in the blank",body:"他买的彩票___奖了。"},{q:"翻译：Be careful not to get heatstroke.",a:"小心中暑。",instr:"翻译",instrEn:"Translate",body:"Be careful not to get heatstroke."},{q:"选择：表示“win a prize”用（中奖 / 中午）。",a:"中奖",instr:"选择",instrEn:"Choose",body:"表示“win a prize”用（中奖 / 中午）。"}],note:"注意读 zhòng，不读 zhōng；常见于固定搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zhòng + object / set word = hit / be struck by / win",noteEn:"Read zhòng, not zhōng; common in set combinations.",typeEn:"Verb"},{id:"HSK6.17.3",name:"副词“姑且”",pinyin:"gūqiě",type:"副词",explainEn:"Use 姑且 to mean “for the time being / tentatively”.",structure:"姑且 + 动词/判断",examples:[{zh:"这个问题我们姑且放一放。",en:"Let us put this issue aside for the time being.",py:"Zhège wèntí wǒmen gūqiě fàng yi fàng."},{zh:"没有更好的办法，就姑且试试这个吧。",en:"Since there is no better way, let us try this for now.",py:"Méiyǒu gèng hǎo de bànfǎ, jiù gūqiě shìshi zhège ba."},{zh:"这件事是真是假，姑且不论。",en:"Whether this is true or false, let us not discuss it for now.",py:"Zhè jiàn shì shì zhēn shì jiǎ, gūqiě bú lùn."}],exercises:[{q:"填空：这个问题我们___放一放。",a:"姑且",instr:"填空",instrEn:"Fill in the blank",body:"这个问题我们___放一放。"},{q:"翻译：Let us try this for now.",a:"我们姑且试试这个。",instr:"翻译",instrEn:"Translate",body:"Let us try this for now."},{q:"选择：表示暂时这样处理，用（姑且 / 统统）。",a:"姑且",instr:"选择",instrEn:"Choose",body:"表示暂时这样处理，用（姑且 / 统统）。"}],note:"有“暂时先这样”的意思，书面语较常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"gūqiě + Verb/judgment = for the time being / tentatively",noteEn:'Means "let it be this way for now"; common in writing.',typeEn:"Adverb"}]},{num:18,title:"神奇的丝瓜",points:[{id:"HSK6.18.1",name:"副词“随即”",pinyin:"suíjí",type:"副词",explainEn:"Use 随即 to mean “immediately afterward / right then”.",structure:"动作1，随即 + 动作2",examples:[{zh:"他看完邮件，随即回复了。",en:"He read the email and replied immediately.",py:"Tā kànwán yóujiàn, suíjí huífù le."},{zh:"会议结束后，大家随即离开。",en:"After the meeting ended, everyone left right away.",py:"Huìyì jiéshù hòu, dàjiā suíjí líkāi."},{zh:"他发现问题，随即采取了措施。",en:"He found the problem and immediately took action.",py:"Tā fāxiàn wèntí, suíjí cǎiqǔle cuòshī."}],exercises:[{q:"填空：他看完邮件，___回复了。",a:"随即",instr:"填空",instrEn:"Fill in the blank",body:"他看完邮件，___回复了。"},{q:"翻译：Everyone left right after the meeting.",a:"会议结束后，大家随即离开。",instr:"翻译",instrEn:"Translate",body:"Everyone left right after the meeting."},{q:"连接：发现问题。马上采取措施。（用“随即”）",a:"他发现问题，随即采取了措施。",instr:"连接",instrEn:"Join the sentences",body:"发现问题。马上采取措施。（用“随即”）"}],note:"比“马上”更书面，强调前后动作紧接发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Action 1, suíjí + Action 2 = then immediately …",noteEn:"More formal than 马上; stresses that the second action follows right after the first.",typeEn:"Adverb"},{id:"HSK6.18.2",name:"副词/能愿结构“宁愿”",pinyin:"nìngyuàn",type:"副词/能愿用法",explainEn:"Use 宁愿 to mean “would rather / prefer to”.",structure:"宁愿 + A，也不/也要 + B",examples:[{zh:"我宁愿走路，也不坐这么挤的车。",en:"I would rather walk than take such a crowded bus.",py:"Wǒ nìngyuàn zǒulù, yě bú zuò zhème jǐ de chē."},{zh:"他宁愿多花时间，也要把事情做好。",en:"He would rather spend more time to do the job well.",py:"Tā nìngyuàn duō huā shíjiān, yě yào bǎ shìqing zuòhǎo."},{zh:"我宁愿自己做，也不麻烦别人。",en:"I would rather do it myself than trouble others.",py:"Wǒ nìngyuàn zìjǐ zuò, yě bù máfan biéren."}],exercises:[{q:"填空：我___走路，也不坐车。",a:"宁愿",instr:"填空",instrEn:"Fill in the blank",body:"我___走路，也不坐车。"},{q:"翻译：He would rather spend more time to do it well.",a:"他宁愿多花时间，也要把事情做好。",instr:"翻译",instrEn:"Translate",body:"He would rather spend more time to do it well."},{q:"连接：自己做；不麻烦别人。（用“宁愿”）",a:"我宁愿自己做，也不麻烦别人。",instr:"连接",instrEn:"Join the sentences",body:"自己做；不麻烦别人。（用“宁愿”）"}],note:"常和“也不、也要”搭配，表达主动选择。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nìngyuàn + A, yě bù/yě yào + B = would rather A than B / would rather A to get B",noteEn:"Often paired with 也不 / 也要 to express a deliberate choice.",typeEn:"Adverb / Modal use"},{id:"HSK6.18.3",name:"让步格式“A归A”",pinyin:"A guī A",type:"让步结构",explainEn:"Use A归A to admit one fact, then add another different point: “A is A, but…”.",structure:"A + 归 + A，(但/可是) + B",examples:[{zh:"贵归贵，质量确实不错。",en:"It is expensive, but the quality is really good.",py:"Guì guī guì, zhìliàng quèshí búcuò."},{zh:"忙归忙，他每天还是会运动。",en:"Busy as he is, he still exercises every day.",py:"Máng guī máng, tā měi tiān háishi huì yùndòng."},{zh:"喜欢归喜欢，我不会买这么贵的。",en:"I like it, but I will not buy something this expensive.",py:"Xǐhuan guī xǐhuan, wǒ bú huì mǎi zhème guì de."}],exercises:[{q:"填空：贵___贵，质量不错。",a:"归",instr:"填空",instrEn:"Fill in the blank",body:"贵___贵，质量不错。"},{q:"翻译：Busy as he is, he still exercises.",a:"忙归忙，他还是会运动。",instr:"翻译",instrEn:"Translate",body:"Busy as he is, he still exercises."},{q:"用“A归A”改写：我喜欢，但是不会买。",a:"喜欢归喜欢，我不会买。"}],note:"前面承认一个事实，后面说明这个事实并不影响另一判断。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + guī + A, (dàn/kěshì) + B = A is A, but B",noteEn:"Admits one fact first, then says it doesn't change another judgment.",typeEn:"Concessive structure"}]},{num:19,title:"无阳光的深海世界",points:[{id:"HSK6.19.1",name:"连词“进而”",pinyin:"jìn’ér",type:"连词",explainEn:"Use 进而 to mean “and then / further”, showing a deeper next step.",structure:"A，进而 + 更进一步的B",examples:[{zh:"先了解问题，进而寻找解决办法。",en:"First understand the problem, then go further to find a solution.",py:"Xiān liǎojiě wèntí, jìn'ér xúnzhǎo jiějué bànfǎ."},{zh:"技术不断进步，进而改变了生活方式。",en:"Technology keeps improving and further changes lifestyles.",py:"Jìshù búduàn jìnbù, jìn'ér gǎibiànle shēnghuó fāngshì."},{zh:"学习语言可以了解文化，进而理解一个社会。",en:"Learning a language can help you understand culture and then society.",py:"Xuéxí yǔyán kěyǐ liǎojiě wénhuà, jìn'ér lǐjiě yí ge shèhuì."}],exercises:[{q:"填空：先了解问题，___寻找办法。",a:"进而",instr:"填空",instrEn:"Fill in the blank",body:"先了解问题，___寻找办法。"},{q:"翻译：Technology improved and further changed life.",a:"技术进步，进而改变了生活。",instr:"翻译",instrEn:"Translate",body:"Technology improved and further changed life."},{q:"连接：了解文化。进一步理解社会。（用“进而”）",a:"了解文化，进而理解社会。",instr:"连接",instrEn:"Join the sentences",body:"了解文化。进一步理解社会。（用“进而”）"}],note:"强调在前一步基础上进一步发展。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A, jìn'ér + a further B = and then, going further, B",noteEn:"Stresses a further step built on the previous one.",typeEn:"Conjunction"},{id:"HSK6.19.2",name:"动词“得以”",pinyin:"déyǐ",type:"动词",explainEn:"Use 得以 before a verb to mean “be able to / get the chance to”, usually because conditions allow it.",structure:"得以 + 动词",examples:[{zh:"问题终于得以解决。",en:"The problem was finally able to be solved.",py:"Wèntí zhōngyú déyǐ jiějué."},{zh:"在大家帮助下，项目得以顺利完成。",en:"With everyone's help, the project was completed successfully.",py:"Zài dàjiā bāngzhù xià, xiàngmù déyǐ shùnlì wánchéng."},{zh:"新技术让更多人得以接受教育。",en:"New technology enables more people to receive education.",py:"Xīn jìshù ràng gèng duō rén déyǐ jiēshòu jiàoyù."}],exercises:[{q:"填空：问题终于___解决。",a:"得以",instr:"填空",instrEn:"Fill in the blank",body:"问题终于___解决。"},{q:"翻译：The project was completed successfully with everyone's help.",a:"在大家帮助下，项目得以顺利完成。",instr:"翻译",instrEn:"Translate",body:"The project was completed successfully with everyone's help."},{q:"选择：表示因条件允许而实现，用（得以 / 难以）。",a:"得以",instr:"选择",instrEn:"Choose",body:"表示因条件允许而实现，用（得以 / 难以）。"}],note:"较正式，常用于积极结果或机会获得。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"déyǐ + Verb = be able to … (thanks to conditions)",noteEn:"Fairly formal; usually for a positive result or a chance gained.",typeEn:"Verb"},{id:"HSK6.19.3",name:"副词“偏偏”",pinyin:"piānpiān",type:"副词",explainEn:"Use 偏偏 when reality goes against expectation or desire: “just / unfortunately / contrary to expectation”.",structure:"想/希望A，偏偏 + B",examples:[{zh:"我最忙的时候，他偏偏来找我。",en:"He came to see me at exactly the time I was busiest.",py:"Wǒ zuì máng de shíhou, tā piānpiān lái zhǎo wǒ."},{zh:"大家都同意，偏偏他反对。",en:"Everyone agreed, but he alone objected.",py:"Dàjiā dōu tóngyì, piānpiān tā fǎnduì."},{zh:"今天想早点儿回家，偏偏下起了大雨。",en:"I wanted to go home early, but it just started pouring.",py:"Jīntiān xiǎng zǎo diǎnr huíjiā, piānpiān xiàqǐle dàyǔ."}],exercises:[{q:"填空：大家都同意，___他反对。",a:"偏偏",instr:"填空",instrEn:"Fill in the blank",body:"大家都同意，___他反对。"},{q:"翻译：He came exactly when I was busiest.",a:"我最忙的时候，他偏偏来找我。",instr:"翻译",instrEn:"Translate",body:"He came exactly when I was busiest."},{q:"连接：我想早点回家。却下大雨。（用“偏偏”）",a:"我想早点儿回家，偏偏下起了大雨。",instr:"连接",instrEn:"Join the sentences",body:"我想早点回家。却下大雨。（用“偏偏”）"}],note:"常带无奈、不满或出乎意料的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"xiǎng/xīwàng A, piānpiān + B = wanted A, but B just had to happen",noteEn:"Often carries helplessness, annoyance, or surprise.",typeEn:"Adverb"}]},{num:20,title:"金鸡窝",points:[{id:"HSK6.20.1",name:"连词“况且”",pinyin:"kuàngqiě",type:"连词",explainEn:"Use 况且 to add a stronger supporting reason: “besides / moreover”.",structure:"理由1，况且 + 理由2",examples:[{zh:"今天太晚了，况且外面还下雨，别出去了。",en:"It is late, and besides, it is raining; do not go out.",py:"Jīntiān tài wǎn le, kuàngqiě wàimiàn hái xià yǔ, bié chūqu le."},{zh:"这件事不急，况且我们还需要更多信息。",en:"This matter is not urgent; moreover, we need more information.",py:"Zhè jiàn shì bù jí, kuàngqiě wǒmen hái xūyào gèng duō xìnxī."},{zh:"他经验丰富，况且准备得很充分，应该没问题。",en:"He is experienced, and besides, he is well prepared, so it should be fine.",py:"Tā jīngyàn fēngfù, kuàngqiě zhǔnbèi de hěn chōngfèn, yīnggāi méi wèntí."}],exercises:[{q:"填空：今天太晚了，___还下雨。",a:"况且",instr:"填空",instrEn:"Fill in the blank",body:"今天太晚了，___还下雨。"},{q:"翻译：Moreover, we need more information.",a:"况且我们还需要更多信息。",instr:"翻译",instrEn:"Translate",body:"Moreover, we need more information."},{q:"给“不去”增加一个更强理由，用“况且”。",a:"太晚了，况且还下雨，我们不去了。"}],note:"常用于第二个理由，使论证更充分。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Reason 1, kuàngqiě + Reason 2 = besides / moreover",noteEn:"Usually introduces a second reason, making the argument stronger.",typeEn:"Conjunction"},{id:"HSK6.20.2",name:"“大 + 时间词”表示特殊时段",pinyin:"dà + shíjiāncí",type:"时间表达",explainEn:"Use 大 + a time word in fixed expressions to strongly mark an unusual time, such as 大清早、大白天、大半夜.",structure:"大清早 / 大白天 / 大半夜",examples:[{zh:"大清早他就出门了。",en:"He went out very early in the morning.",py:"Dà qīngzǎo tā jiù chūmén le."},{zh:"大白天的，你怕什么？",en:"It is broad daylight; what are you afraid of?",py:"Dà báitiān de, nǐ pà shénme?"},{zh:"大半夜别给别人打电话。",en:"Do not call people in the middle of the night.",py:"Dà bànyè bié gěi biéren dǎ diànhuà."}],exercises:[{q:"填空：___清早他就出门了。",a:"大",instr:"填空",instrEn:"Fill in the blank",body:"___清早他就出门了。"},{q:"翻译：Do not call people in the middle of the night.",a:"大半夜别给别人打电话。",instr:"翻译",instrEn:"Translate",body:"Do not call people in the middle of the night."},{q:"选择：broad daylight =（大白天 / 大晚上）。",a:"大白天",instr:"选择",instrEn:"Choose",body:"broad daylight =（大白天 / 大晚上）。"}],note:"多为固定搭配，常带强调、惊讶或不满。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dà qīngzǎo / dà báitiān / dà bànyè = so early in the morning / in broad daylight / in the dead of night",noteEn:"Mostly set combinations; often adds emphasis, surprise or annoyance.",typeEn:"Time"},{id:"HSK6.20.3",name:"选择格式“与其……倒不如……”",pinyin:"yǔqí ... dào bùrú ...",type:"选择复句",explainEn:"Use 与其…倒不如… to mean “rather than…, it would be better to…”.",structure:"与其 + A，倒不如 + B",examples:[{zh:"与其一直担心，倒不如马上行动。",en:"Rather than keep worrying, it is better to act now.",py:"Yǔqí yìzhí dānxīn, dào bùrú mǎshàng xíngdòng."},{zh:"与其开车堵在路上，倒不如坐地铁。",en:"Rather than get stuck driving, it is better to take the subway.",py:"Yǔqí kāichē dǔ zài lù shang, dào bùrú zuò dìtiě."},{zh:"与其勉强答应，倒不如直接说明。",en:"Rather than agree unwillingly, it is better to explain directly.",py:"Yǔqí miǎnqiǎng dāying, dào bùrú zhíjiē shuōmíng."}],exercises:[{q:"填空：___一直担心，___马上行动。",a:"与其；倒不如",instr:"填空",instrEn:"Fill in the blank",body:"___一直担心，___马上行动。"},{q:"翻译：Rather than drive, it is better to take the subway.",a:"与其开车，倒不如坐地铁。",instr:"翻译",instrEn:"Translate",body:"Rather than drive, it is better to take the subway."},{q:"连接：勉强答应不好；直接说明更好。",a:"与其勉强答应，倒不如直接说明。",instr:"连接",instrEn:"Join the sentences",body:"勉强答应不好；直接说明更好。"}],note:"“倒不如”比“不如”更有“反而选择这个更好”的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yǔqí + A, dào bùrú + B = rather than A, it'd be better to B",noteEn:'倒不如 adds more of a "better to choose this instead" tone than 不如.',typeEn:"Alternative clause"}]},{num:21,title:"未来商店",points:[{id:"HSK6.21.1",name:"连词“以免”",pinyin:"yǐmiǎn",type:"目的连词",explainEn:"Use 以免 to mean “so as to avoid / lest”, usually before an unwanted result.",structure:"动作/措施 + 以免 + 不好的结果",examples:[{zh:"请提前出发，以免迟到。",en:"Please leave early so as not to be late.",py:"Qǐng tíqián chūfā, yǐmiǎn chídào."},{zh:"重要文件要备份，以免丢失。",en:"Back up important files to avoid losing them.",py:"Zhòngyào wénjiàn yào bèifèn, yǐmiǎn diūshī."},{zh:"出门带把伞，以免下雨。",en:"Take an umbrella in case it rains.",py:"Chūmén dài bǎ sǎn, yǐmiǎn xià yǔ."}],exercises:[{q:"填空：提前出发，___迟到。",a:"以免",instr:"填空",instrEn:"Fill in the blank",body:"提前出发，___迟到。"},{q:"翻译：Back up the files so they are not lost.",a:"重要文件要备份，以免丢失。",instr:"翻译",instrEn:"Translate",body:"Back up the files so they are not lost."},{q:"连接：带伞。避免下雨时没伞。",a:"出门带把伞，以免下雨。",instr:"连接",instrEn:"Join the sentences",body:"带伞。避免下雨时没伞。"}],note:"较书面；和“免得”接近，常用于提醒和说明预防措施。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Action / measure + yǐmiǎn + bad result = so as to avoid …",noteEn:"Fairly formal; close to 免得; used in reminders and to explain precautions.",typeEn:"Purpose conjunction"},{id:"HSK6.21.2",name:"动词“嫌”引出评价",pinyin:"xián",type:"兼语/动词",explainEn:"Use 嫌 to mean “dislike / think something is too…”.",structure:"嫌 + 名词 + 形容词/小句；嫌 + 形容词",examples:[{zh:"我嫌这个房间太小。",en:"I think this room is too small.",py:"Wǒ xián zhège fángjiān tài xiǎo."},{zh:"他嫌路远，不想去。",en:"He thinks the road is too far and does not want to go.",py:"Tā xián lù yuǎn, bù xiǎng qù."},{zh:"别嫌麻烦，再检查一遍。",en:"Do not think it is too troublesome; check it again.",py:"Bié xián máfan, zài jiǎnchá yí biàn."}],exercises:[{q:"填空：我___这个房间太小。",a:"嫌",instr:"填空",instrEn:"Fill in the blank",body:"我___这个房间太小。"},{q:"翻译：He thinks the road is too far.",a:"他嫌路远。",instr:"翻译",instrEn:"Translate",body:"He thinks the road is too far."},{q:"选择：表示“不满意太麻烦”用（嫌麻烦 / 便于麻烦）。",a:"嫌麻烦",instr:"选择",instrEn:"Choose",body:"表示“不满意太麻烦”用（嫌麻烦 / 便于麻烦）。"}],note:"“嫌 + 宾语 + 形容词”中，宾语也是后面状态的主体。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"xián + Noun + Adj/Clause; xián + Adj = find (sb/sth) too … / dislike that …",noteEn:"In 嫌 + object + adjective, the object is also the one who has that state.",typeEn:"Pivot verb"}]},{num:22,title:"2050年的汽车什么样",points:[{id:"HSK6.22.1",name:"固定用法“动不动”",pinyin:"dòngbudòng",type:"固定用法",explainEn:"Use 动不动 to mean “at the slightest thing / often and easily”.",structure:"动不动 + 就 + 动词",examples:[{zh:"他动不动就生气。",en:"He gets angry at the slightest thing.",py:"Tā dòngbudòng jiù shēngqì."},{zh:"这台旧电脑动不动就死机。",en:"This old computer crashes all the time.",py:"Zhè tái jiù diànnǎo dòngbudòng jiù sǐjī."},{zh:"孩子动不动就说不想上学。",en:"The child often says he does not want to go to school.",py:"Háizi dòngbudòng jiù shuō bù xiǎng shàngxué."}],exercises:[{q:"填空：他___就生气。",a:"动不动",instr:"填空",instrEn:"Fill in the blank",body:"他___就生气。"},{q:"翻译：This old computer crashes all the time.",a:"这台旧电脑动不动就死机。",instr:"翻译",instrEn:"Translate",body:"This old computer crashes all the time."},{q:"选择：表示很容易发生，用（动不动就 / 预先）。",a:"动不动就",instr:"选择",instrEn:"Choose",body:"表示很容易发生，用（动不动就 / 预先）。"}],note:"常带负面评价，表示某事太容易或太频繁发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dòngbudòng + jiù + Verb = at the slightest thing …",noteEn:"Often negative; says something happens too easily or too often.",typeEn:"Set usage"},{id:"HSK6.22.2",name:"列举用“甲乙丙丁……”",pinyin:"jiǎ yǐ bǐng dīng ...",type:"列举/代称",explainEn:"Use 甲、乙、丙、丁 as neutral labels like A, B, C, D when listing people, plans, groups, etc.",structure:"甲、乙、丙、丁……",examples:[{zh:"我们把方案分成甲、乙、丙三种。",en:"We divide the plans into A, B, and C.",py:"Wǒmen bǎ fāng'àn fēnchéng jiǎ, yǐ, bǐng sān zhǒng."},{zh:"甲方负责提供材料，乙方负责施工。",en:"Party A provides the materials; Party B handles construction.",py:"Jiǎfāng fùzé tígōng cáiliào, yǐfāng fùzé shīgōng."},{zh:"比赛分甲、乙两个小组。",en:"The competition is divided into Group A and Group B.",py:"Bǐsài fēn jiǎ, yǐ liǎng ge xiǎozǔ."}],exercises:[{q:"填空：___方负责提供材料，乙方负责施工。",a:"甲",instr:"填空",instrEn:"Fill in the blank",body:"___方负责提供材料，乙方负责施工。"},{q:"翻译：The plans are divided into A, B, and C.",a:"方案分成甲、乙、丙三种。",instr:"翻译",instrEn:"Translate",body:"The plans are divided into A, B, and C."},{q:"选择：正式合同中的A/B parties常写（甲方乙方 / 左方右方）。",a:"甲方乙方",instr:"选择",instrEn:"Choose",body:"正式合同中的A/B parties常写（甲方乙方 / 左方右方）。"}],note:"多用于编号、合同、比赛分组或抽象列举。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jiǎ, yǐ, bǐng, dīng … = A, B, C, D … (as labels)",noteEn:"Used for numbering, contracts, competition groups, or abstract lists.",typeEn:"Listing labels"}]},{num:23,title:"大数据时代",points:[{id:"HSK6.23.1",name:"形式动词“加以”",pinyin:"jiāyǐ",type:"形式动词",explainEn:"Use 加以 before a two-syllable verb to mean “carry out / give…to”, in formal writing.",structure:"加以 + 双音节动词",examples:[{zh:"这个问题需要加以解决。",en:"This problem needs to be solved.",py:"Zhège wèntí xūyào jiāyǐ jiějué."},{zh:"我们会认真研究并加以改进。",en:"We will study it carefully and improve it.",py:"Wǒmen huì rènzhēn yánjiū bìng jiāyǐ gǎijìn."},{zh:"这些文化遗产应该加以保护。",en:"These cultural heritage sites should be protected.",py:"Zhèxiē wénhuà yíchǎn yīnggāi jiāyǐ bǎohù."}],exercises:[{q:"填空：问题需要___解决。",a:"加以",instr:"填空",instrEn:"Fill in the blank",body:"问题需要___解决。"},{q:"翻译：These cultural heritage sites should be protected.",a:"这些文化遗产应该加以保护。",instr:"翻译",instrEn:"Translate",body:"These cultural heritage sites should be protected."},{q:"选择：正式表达“give protection”用（加以保护 / 加着保护）。",a:"加以保护",instr:"选择",instrEn:"Choose",body:"正式表达“give protection”用（加以保护 / 加着保护）。"}],note:"后面多接双音节动词，如“说明、分析、保护、处理、改进”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jiāyǐ + two-syllable Verb = give … / carry out … (formal)",noteEn:"Usually followed by a two-syllable verb such as 说明, 分析, 保护, 处理, 改进.",typeEn:"Dummy verb"},{id:"HSK6.23.2",name:"重叠形式“大大、远远”",pinyin:"dàdà, yuǎnyuǎn",type:"程度副词",explainEn:"Use 大大 or 远远 before a verb/adjective to strongly increase degree or difference.",structure:"大大 + 提高/降低/超过；远远 + 高于/低于/超过",examples:[{zh:"这个办法大大提高了效率。",en:"This method greatly improved efficiency.",py:"Zhège bànfǎ dàdà tígāole xiàolǜ."},{zh:"结果远远超过了我们的预期。",en:"The result far exceeded our expectations.",py:"Jiéguǒ yuǎnyuǎn chāoguòle wǒmen de yùqī."},{zh:"新设备使成本大大降低。",en:"The new equipment greatly reduced costs.",py:"Xīn shèbèi shǐ chéngběn dàdà jiàngdī."}],exercises:[{q:"填空：这个办法___提高了效率。",a:"大大",instr:"填空",instrEn:"Fill in the blank",body:"这个办法___提高了效率。"},{q:"翻译：The result far exceeded our expectations.",a:"结果远远超过了我们的预期。",instr:"翻译",instrEn:"Translate",body:"The result far exceeded our expectations."},{q:"选择：表示“far higher than”用（远远高于 / 大大于）。",a:"远远高于",instr:"选择",instrEn:"Choose",body:"表示“far higher than”用（远远高于 / 大大于）。"}],note:"这类重叠形式常作程度副词，强调变化大或差距远。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dàdà + tígāo/jiàngdī/chāoguò; yuǎnyuǎn + gāoyú/dīyú/chāoguò = greatly …; far …",noteEn:"These reduplicated forms work as degree adverbs, stressing a big change or a wide gap.",typeEn:"Degree adverb"}]},{num:24,title:"体育明星们的离奇遭遇",points:[{id:"HSK6.24.1",name:"紧缩句",pinyin:"jǐnsuō jù",type:"复句结构",explainEn:"A 紧缩句 compresses a complex sentence into a short form, often without a pause or full conjunction pair.",structure:"压缩条件/让步等关系：A + B（如“不喜欢就不买”）",examples:[{zh:"不喜欢就别买。",en:"If you do not like it, do not buy it.",py:"Bù xǐhuan jiù bié mǎi."},{zh:"她一回来我就告诉你。",en:"As soon as she comes back, I will tell you.",py:"Tā yì huílai wǒ jiù gàosu nǐ."},{zh:"想赢也不能违反规则。",en:"Even if you want to win, you cannot break the rules.",py:"Xiǎng yíng yě bù néng wéifǎn guīzé."}],exercises:[{q:"把“如果不喜欢，就别买”改成紧缩句。",a:"不喜欢就别买。"},{q:"翻译：As soon as she comes back, I will tell you.",a:"她一回来我就告诉你。",instr:"翻译",instrEn:"Translate",body:"As soon as she comes back, I will tell you."},{q:"把“即使想赢，也不能违反规则”压缩。",a:"想赢也不能违反规则。"}],note:"看起来像单句，但实际包含条件、让步、承接等复句关系。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Compressed condition / concession: A + B (e.g. bù xǐhuan jiù bù mǎi) = if/even if A, B",noteEn:"Looks like a simple sentence but actually contains a conditional, concessive or sequential relation.",typeEn:"Complex sentence"},{id:"HSK6.24.2",name:"副词“特意”",pinyin:"tèyì",type:"副词",explainEn:"Use 特意 to mean “specially / intentionally for a good or specific purpose”.",structure:"特意 + 动词",examples:[{zh:"我特意来看看你。",en:"I came specially to see you.",py:"Wǒ tèyì lái kànkan nǐ."},{zh:"为了这次会议，他特意准备了资料。",en:"He specially prepared materials for this meeting.",py:"Wèile zhè cì huìyì, tā tèyì zhǔnbèile zīliào."},{zh:"妈妈特意做了我最喜欢的菜。",en:"Mom specially cooked my favorite dish.",py:"Māma tèyì zuòle wǒ zuì xǐhuan de cài."}],exercises:[{q:"填空：我___来看看你。",a:"特意",instr:"填空",instrEn:"Fill in the blank",body:"我___来看看你。"},{q:"翻译：He specially prepared materials for the meeting.",a:"他特意准备了资料。",instr:"翻译",instrEn:"Translate",body:"He specially prepared materials for the meeting."},{q:"选择：为了别人或某目的专门做，用（特意 / 故意）。",a:"特意",instr:"选择",instrEn:"Choose",body:"为了别人或某目的专门做，用（特意 / 故意）。"}],note:"通常有明确目的，感情色彩中性或积极；不要和常带贬义的“故意”混淆。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"tèyì + Verb = do … specially (for a purpose)",noteEn:"Usually has a clear purpose, neutral or positive; don't confuse it with 故意, which is often negative.",typeEn:"Adverb"}]},{num:25,title:"草船借箭",points:[{id:"HSK6.25.1",name:"副词“即将”",pinyin:"jíjiāng",type:"副词",explainEn:"Use 即将 to mean “be about to / soon will”. It is formal.",structure:"即将 + 动词/变化",examples:[{zh:"会议即将开始。",en:"The meeting is about to begin.",py:"Huìyì jíjiāng kāishǐ."},{zh:"我们即将进入考试周。",en:"We are about to enter exam week.",py:"Wǒmen jíjiāng jìnrù kǎoshì zhōu."},{zh:"新产品即将上市。",en:"The new product will be launched soon.",py:"Xīn chǎnpǐn jíjiāng shàngshì."}],exercises:[{q:"填空：会议___开始。",a:"即将",instr:"填空",instrEn:"Fill in the blank",body:"会议___开始。"},{q:"翻译：The new product will be launched soon.",a:"新产品即将上市。",instr:"翻译",instrEn:"Translate",body:"The new product will be launched soon."},{q:"选择：较正式的“about to”用（即将 / 偶尔）。",a:"即将",instr:"选择",instrEn:"Choose",body:"较正式的“about to”用（即将 / 偶尔）。"}],note:"常见于新闻、通知、正式说明。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"jíjiāng + Verb / change = be about to …",noteEn:"Common in news, notices and formal statements.",typeEn:"Adverb"},{id:"HSK6.25.2",name:"固定格式“能A就A”",pinyin:"néng A jiù A",type:"固定格式",explainEn:"Use 能A就A to mean “do as much/as soon/as well as you can”.",structure:"能 + 动词/形容词 + 就 + 同一动词/形容词",examples:[{zh:"能早点儿走就早点儿走。",en:"Leave as early as you can.",py:"Néng zǎo diǎnr zǒu jiù zǎo diǎnr zǒu."},{zh:"能帮一点儿就帮一点儿。",en:"Help as much as you can.",py:"Néng bāng yìdiǎnr jiù bāng yìdiǎnr."},{zh:"能省就省，别乱花钱。",en:"Save as much as you can; do not waste money.",py:"Néng shěng jiù shěng, bié luàn huā qián."}],exercises:[{q:"填空：能早点儿走___早点儿走。",a:"就",instr:"填空",instrEn:"Fill in the blank",body:"能早点儿走___早点儿走。"},{q:"翻译：Help as much as you can.",a:"能帮一点儿就帮一点儿。",instr:"翻译",instrEn:"Translate",body:"Help as much as you can."},{q:"用该格式表达：能省钱就尽量省钱。",a:"能省就省。"}],note:"强调在条件允许的范围内尽量做到。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"néng + Verb/Adj + jiù + same Verb/Adj = … as much as you can",noteEn:"Stresses doing as much as conditions allow.",typeEn:"Fixed pattern"}]},{num:26,title:"奇异的灯光",points:[{id:"HSK6.26.1",name:"连词“别说”",pinyin:"biéshuō",type:"连词",explainEn:"Use 别说 to introduce a stronger comparison: “let alone / not to mention”.",structure:"别说 + 较难情况，连/就是 + 较容易情况 + 都/也……",examples:[{zh:"别说跑十公里了，跑一公里我都累。",en:"Let alone running ten kilometers; even one kilometer tires me.",py:"Biéshuō pǎo shí gōnglǐ le, pǎo yì gōnglǐ wǒ dōu lèi."},{zh:"别说外国人，有些中国人也不认识这个字。",en:"Not to mention foreigners; even some Chinese people do not know this character.",py:"Biéshuō wàiguórén, yǒuxiē Zhōngguórén yě bú rènshi zhège zì."},{zh:"别说买房了，现在连房租都很贵。",en:"Let alone buying a home; even rent is expensive now.",py:"Biéshuō mǎi fáng le, xiànzài lián fángzū dōu hěn guì."}],exercises:[{q:"填空：___跑十公里了，一公里我都累。",a:"别说",instr:"填空",instrEn:"Fill in the blank",body:"___跑十公里了，一公里我都累。"},{q:"翻译：Let alone buying a home; even rent is expensive.",a:"别说买房了，连房租都很贵。",instr:"翻译",instrEn:"Translate",body:"Let alone buying a home; even rent is expensive."},{q:"连接：十公里不行；一公里也累。（用“别说”）",a:"别说十公里了，一公里我都累。",instr:"连接",instrEn:"Join the sentences",body:"十公里不行；一公里也累。（用“别说”）"}],note:"通过较极端情况来强调连较普通情况都难以达到。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"biéshuō + harder case, lián/jiùshì + easier case + dōu/yě … = let alone … , even … not …",noteEn:"Uses an extreme case to stress that even the ordinary case is hard to reach.",typeEn:"Conjunction"},{id:"HSK6.26.2",name:"AABB式重叠“来来回回”等",pinyin:"AABB shì chóngdié",type:"重叠结构",explainEn:"Some two-syllable words can repeat as AABB to stress repeated, continuous, or distributed action/state.",structure:"AB → AABB",examples:[{zh:"他在门口来来回回走了半天。",en:"He walked back and forth at the door for a long time.",py:"Tā zài ménkǒu láiláihuíhuí zǒule bàntiān."},{zh:"大家说说笑笑地吃完了饭。",en:"Everyone ate while chatting and laughing.",py:"Dàjiā shuōshuōxiàoxiào de chīwánle fàn."},{zh:"她认认真真地检查了一遍。",en:"She checked it very carefully.",py:"Tā rènrènzhēnzhēn de jiǎnchále yí biàn."}],exercises:[{q:"把“来回”改成AABB式。",a:"来来回回"},{q:"翻译：She checked it very carefully.",a:"她认认真真地检查了一遍。",instr:"翻译",instrEn:"Translate",body:"She checked it very carefully."},{q:"选择：表示反复来回用（来来回回 / 来回来回）。",a:"来来回回",instr:"选择",instrEn:"Choose",body:"表示反复来回用（来来回回 / 来回来回）。"}],note:"不同词重叠后的意义不同，常强调反复、程度或生动感。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"AB → AABB = repeated / vivid form (láiláihuíhuí = back and forth)",noteEn:"Different words mean different things when reduplicated; often stresses repetition, degree or vividness.",typeEn:"Reduplication"}]},{num:27,title:"完璧归赵",points:[{id:"HSK6.27.1",name:"固定格式“左……右……”",pinyin:"zuǒ ... yòu ...",type:"固定格式",explainEn:"Use 左…右… with verbs to show repeated action in different directions or repeated attempts.",structure:"左 + 动词A + 右 + 动词B",examples:[{zh:"我左想右想，还是决定去。",en:"I thought it over again and again and still decided to go.",py:"Wǒ zuǒ xiǎng yòu xiǎng, háishi juédìng qù."},{zh:"他左看右看，没找到出口。",en:"He looked left and right but did not find the exit.",py:"Tā zuǒ kàn yòu kàn, méi zhǎodào chūkǒu."},{zh:"大家左等右等，他还是没来。",en:"Everyone waited and waited, but he still did not come.",py:"Dàjiā zuǒ děng yòu děng, tā háishi méi lái."}],exercises:[{q:"填空：我左想___想。",a:"右",instr:"填空",instrEn:"Fill in the blank",body:"我左想___想。"},{q:"翻译：He looked around but did not find the exit.",a:"他左看右看，没找到出口。",instr:"翻译",instrEn:"Translate",body:"He looked around but did not find the exit."},{q:"写一个“左……右……”表示反复等待的短语。",a:"左等右等"}],note:"A、B多为相同或相关动词，表示反复、到处或多次尝试。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zuǒ + Verb A + yòu + Verb B = A again and again",noteEn:"A and B are usually the same or related verbs; shows repeated action, everywhere, or many attempts.",typeEn:"Fixed pattern"},{id:"HSK6.27.2",name:"句末“……不成？”",pinyin:"... bùchéng?",type:"反问/推测结构",explainEn:"Use 不成 at the end of a question to show doubt or rhetorical surprise: “could it be that…?”.",structure:"难道/莫非 + 小句 + 不成？；小句 + 不成？",examples:[{zh:"难道你想一个人去不成？",en:"Could it be that you want to go alone?",py:"Nándào nǐ xiǎng yí ge rén qù bùchéng?"},{zh:"他这么久没来，出什么事了不成？",en:"He has not come for so long; could something have happened?",py:"Tā zhème jiǔ méi lái, chū shénme shì le bùchéng?"},{zh:"你还真打算放弃不成？",en:"Are you really planning to give up?",py:"Nǐ hái zhēn dǎsuàn fàngqì bùchéng?"}],exercises:[{q:"填空：难道你想走___？",a:"不成",instr:"填空",instrEn:"Fill in the blank",body:"难道你想走___？"},{q:"翻译：Could something have happened?",a:"出什么事了不成？",instr:"翻译",instrEn:"Translate",body:"Could something have happened?"},{q:"用“不成”加强疑问：你真的要放弃？",a:"你真的要放弃不成？"}],note:"多用于反问或猜测，语气较强，常带惊讶或不同意。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nándào/mòfēi + Clause + bùchéng? ; Clause + bùchéng? = could it be that …?",noteEn:"Mostly in rhetorical questions or guesses; a strong tone, often surprise or disagreement.",typeEn:"Rhetorical / Guessing"}]},{num:28,title:"高山流水遇知音",points:[{id:"HSK6.28.1",name:"与“个”相关的格式",pinyin:"yǔ “gè” xiāngguān de géshì",type:"结构",explainEn:"Two useful patterns with 个: “一个 + noun/verb phrase” can show a sudden action; “V + (了)个 + result” introduces a result vividly.",structure:"一个 + 名词/动词结构 + V；V +（了）个 + 形容词/动词结果",examples:[{zh:"他一个不小心，把杯子打碎了。",en:"He accidentally broke the cup in one careless moment.",py:"Tā yí ge bù xiǎoxīn, bǎ bēizi dǎsuì le."},{zh:"孩子一个跟头摔倒了。",en:"The child fell over in a sudden tumble.",py:"Háizi yí ge gēntou shuāidǎo le."},{zh:"他把房间收拾了个干干净净。",en:"He cleaned the room completely.",py:"Tā bǎ fángjiān shōushile ge gāngānjìngjìng."}],exercises:[{q:"填空：他一个不___，把手机掉了。",a:"小心",instr:"填空",instrEn:"Fill in the blank",body:"他一个不___，把手机掉了。"},{q:"翻译：He cleaned the room completely.",a:"他把房间收拾了个干干净净。",instr:"翻译",instrEn:"Translate",body:"He cleaned the room completely."},{q:"用“V了个+结果”表达：大家笑得非常开心。",a:"大家笑了个痛快。"}],note:"教材把两类“个”格式放在一起：一类突出突然发生，一类生动引出动作结果。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yí ge + Noun/verb phrase + V; V + (le) ge + Adj/Verb result = suddenly …; V till it ends up …",noteEn:"The textbook groups two 个 patterns: one shows something happening suddenly, the other vividly introduces a result.",typeEn:"Structure"},{id:"HSK6.28.2",name:"副词“向来”",pinyin:"xiànglái",type:"副词",explainEn:"Use 向来 to mean “always / all along” from the past until now.",structure:"向来 + 谓语",examples:[{zh:"他做事向来认真。",en:"He has always been serious about his work.",py:"Tā zuòshì xiànglái rènzhēn."},{zh:"这里向来很安静。",en:"This place has always been quiet.",py:"Zhèlǐ xiànglái hěn ānjìng."},{zh:"我向来不喜欢迟到。",en:"I have never liked being late.",py:"Wǒ xiànglái bù xǐhuan chídào."}],exercises:[{q:"填空：他做事___认真。",a:"向来",instr:"填空",instrEn:"Fill in the blank",body:"他做事___认真。"},{q:"翻译：This place has always been quiet.",a:"这里向来很安静。",instr:"翻译",instrEn:"Translate",body:"This place has always been quiet."},{q:"选择：表示“一直以来”用（向来 / 一时）。",a:"向来",instr:"选择",instrEn:"Choose",body:"表示“一直以来”用（向来 / 一时）。"}],note:"强调从过去到现在一贯如此。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"xiànglái + predicate = always (has been) …",noteEn:"Stresses that something has always been so, from the past until now.",typeEn:"Adverb"}]},{num:29,title:"“笑”的备忘录",points:[{id:"HSK6.29.1",name:"副词“预先”",pinyin:"yùxiān",type:"副词",explainEn:"Use 预先 to mean “in advance / beforehand”.",structure:"预先 + 动词",examples:[{zh:"请预先准备好材料。",en:"Please prepare the materials in advance.",py:"Qǐng yùxiān zhǔnbèi hǎo cáiliào."},{zh:"我们已经预先订好了房间。",en:"We booked the room in advance.",py:"Wǒmen yǐjīng yùxiān dìnghǎole fángjiān."},{zh:"重要情况要预先说明。",en:"Important circumstances should be explained beforehand.",py:"Zhòngyào qíngkuàng yào yùxiān shuōmíng."}],exercises:[{q:"填空：请___准备材料。",a:"预先",instr:"填空",instrEn:"Fill in the blank",body:"请___准备材料。"},{q:"翻译：We booked the room in advance.",a:"我们预先订好了房间。",instr:"翻译",instrEn:"Translate",body:"We booked the room in advance."},{q:"选择：beforehand =（预先 / 随即）。",a:"预先",instr:"选择",instrEn:"Choose",body:"beforehand =（预先 / 随即）。"}],note:"比“提前”更书面。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yùxiān + Verb = do … in advance",noteEn:"More formal than 提前.",typeEn:"Adverb"},{id:"HSK6.29.2",name:"让步列举“……也好，……也罢”",pinyin:"... yě hǎo, ... yě bà",type:"让步/列举结构",explainEn:"Use …也好，…也罢 to mean “whether…or… / be it…or…”, showing the result is the same.",structure:"A + 也好，B + 也罢，+ 不变结果",examples:[{zh:"成功也好，失败也罢，我们都要认真总结。",en:"Whether we succeed or fail, we should summarize carefully.",py:"Chénggōng yě hǎo, shībài yě bà, wǒmen dōu yào rènzhēn zǒngjié."},{zh:"你去也好，不去也罢，都要早点儿决定。",en:"Whether you go or not, decide early.",py:"Nǐ qù yě hǎo, bú qù yě bà, dōu yào zǎo diǎnr juédìng."},{zh:"工作也好，学习也罢，态度都很重要。",en:"Whether at work or study, attitude is important.",py:"Gōngzuò yě hǎo, xuéxí yě bà, tàidu dōu hěn zhòngyào."}],exercises:[{q:"填空：成功___，失败___，都要总结。",a:"也好；也罢",instr:"填空",instrEn:"Fill in the blank",body:"成功___，失败___，都要总结。"},{q:"翻译：Whether you go or not, decide early.",a:"你去也好，不去也罢，都要早点儿决定。",instr:"翻译",instrEn:"Translate",body:"Whether you go or not, decide early."},{q:"用该结构表达：工作或学习，态度都重要。",a:"工作也好，学习也罢，态度都很重要。"}],note:"A、B通常是两种可能，后面的态度或结果不变。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + yě hǎo, B + yě bà, + unchanged result = whether A or B, …",noteEn:"A and B are usually two possibilities; the attitude or result after them stays the same.",typeEn:"Concessive / Listing"}]},{num:30,title:"你睡好了吗",points:[{id:"HSK6.30.1",name:"副词“不时”",pinyin:"bùshí",type:"副词",explainEn:"Use 不时 to mean “from time to time / now and then”.",structure:"不时 + 动词",examples:[{zh:"他工作的时候不时看看手机。",en:"He looks at his phone from time to time while working.",py:"Tā gōngzuò de shíhou bùshí kànkan shǒujī."},{zh:"外面不时传来汽车声。",en:"Car sounds come from outside from time to time.",py:"Wàimiàn bùshí chuánlái qìchē shēng."},{zh:"她说话时不时笑一笑。",en:"She smiles now and then while speaking.",py:"Tā shuōhuà shí bùshí xiào yi xiào."}],exercises:[{q:"填空：他___看看手机。",a:"不时",instr:"填空",instrEn:"Fill in the blank",body:"他___看看手机。"},{q:"翻译：Car sounds come from outside from time to time.",a:"外面不时传来汽车声。",instr:"翻译",instrEn:"Translate",body:"Car sounds come from outside from time to time."},{q:"选择：now and then =（不时 / 务必）。",a:"不时",instr:"选择",instrEn:"Choose",body:"now and then =（不时 / 务必）。"}],note:"比“偶尔”更强调在一段时间里间歇性地多次发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùshí + Verb = from time to time …",noteEn:"Stresses repeated, intermittent happenings over a period, more than 偶尔.",typeEn:"Adverb"},{id:"HSK6.30.2",name:"副词“多多少少”",pinyin:"duōduōshǎoshǎo",type:"副词",explainEn:"Use 多多少少 to mean “more or less / to some extent”.",structure:"多多少少 + 谓语",examples:[{zh:"这件事对他多多少少有些影响。",en:"This matter affected him to some extent.",py:"Zhè jiàn shì duì tā duōduōshǎoshǎo yǒuxiē yǐngxiǎng."},{zh:"学过一年中文的人多多少少能听懂一点儿。",en:"Someone who studied Chinese for a year can understand a little to some extent.",py:"Xuéguo yì nián Zhōngwén de rén duōduōshǎoshǎo néng tīngdǒng yìdiǎnr."},{zh:"每个人多多少少都会遇到压力。",en:"Everyone experiences some pressure to some extent.",py:"Měi ge rén duōduōshǎoshǎo dōu huì yùdào yālì."}],exercises:[{q:"填空：这件事___有些影响。",a:"多多少少",instr:"填空",instrEn:"Fill in the blank",body:"这件事___有些影响。"},{q:"翻译：Everyone experiences some pressure to some extent.",a:"每个人多多少少都会遇到压力。",instr:"翻译",instrEn:"Translate",body:"Everyone experiences some pressure to some extent."},{q:"选择：表示“more or less”用（多多少少 / 统统）。",a:"多多少少",instr:"选择",instrEn:"Choose",body:"表示“more or less”用（多多少少 / 统统）。"}],note:"表示程度或数量不是很精确，但多少有一点。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"duōduōshǎoshǎo + predicate = more or less …",noteEn:"The degree or amount isn't exact, but there is at least some.",typeEn:"Adverb"}]},{num:31,title:"运动的学问",points:[{id:"HSK6.31.1",name:"介词/构词成分“逐”",pinyin:"zhú",type:"介词/构词成分",explainEn:"Use 逐 to mean “one by one / each / step by step”, mostly in formal expressions.",structure:"逐 + 个/项/年/日/步 + 动词/变化",examples:[{zh:"请逐项检查这些内容。",en:"Please check these items one by one.",py:"Qǐng zhúxiàng jiǎnchá zhèxiē nèiróng."},{zh:"公司的收入逐年增加。",en:"The company's income increases year by year.",py:"Gōngsī de shōurù zhúnián zēngjiā."},{zh:"问题正在逐步解决。",en:"The problem is being solved step by step.",py:"Wèntí zhèngzài zhúbù jiějué."}],exercises:[{q:"填空：请___项检查。",a:"逐",instr:"填空",instrEn:"Fill in the blank",body:"请___项检查。"},{q:"翻译：The income increases year by year.",a:"公司的收入逐年增加。",instr:"翻译",instrEn:"Translate",body:"The income increases year by year."},{q:"选择：step by step =（逐步 / 一时）。",a:"逐步",instr:"选择",instrEn:"Choose",body:"step by step =（逐步 / 一时）。"}],note:"常见固定搭配：逐个、逐项、逐年、逐日、逐步。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zhú + gè/xiàng/nián/rì/bù + Verb/change = one by one / item by item / year by year / step by step",noteEn:"Common set combinations: 逐个, 逐项, 逐年, 逐日, 逐步.",typeEn:"Preposition / Word-forming element"},{id:"HSK6.31.2",name:"插入语“归根到底”",pinyin:"guīgēn dàodǐ",type:"插入语",explainEn:"Use 归根到底 to mean “in the final analysis / fundamentally”.",structure:"归根到底，+ 最根本的原因/结论",examples:[{zh:"归根到底，健康最重要。",en:"In the final analysis, health is the most important.",py:"Guīgēn dàodǐ, jiànkāng zuì zhòngyào."},{zh:"这个问题归根到底还是沟通不够。",en:"Fundamentally, this problem is still caused by poor communication.",py:"Zhège wèntí guīgēn dàodǐ háishi gōutōng bú gòu."},{zh:"方法很多，归根到底还是要坚持。",en:"There are many methods, but in the end you still need persistence.",py:"Fāngfǎ hěn duō, guīgēn dàodǐ háishi yào jiānchí."}],exercises:[{q:"填空：___，还是沟通的问题。",a:"归根到底",instr:"填空",instrEn:"Fill in the blank",body:"___，还是沟通的问题。"},{q:"翻译：Fundamentally, health is the most important.",a:"归根到底，健康最重要。",instr:"翻译",instrEn:"Translate",body:"Fundamentally, health is the most important."},{q:"用“归根到底”总结：方法很多，最重要的是坚持。",a:"方法很多，归根到底还是要坚持。"}],note:"用于总结最根本的原因、本质或结论。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"guīgēn dàodǐ, + root cause / conclusion = in the final analysis, …",noteEn:"Sums up the most basic cause, nature or conclusion.",typeEn:"Parenthetical"}]},{num:32,title:"有时，不妨悲伤",points:[{id:"HSK6.32.1",name:"连词“哪怕”",pinyin:"nǎpà",type:"连词",explainEn:"Use 哪怕 to mean “even if”, often for an extreme or unfavorable condition.",structure:"哪怕 + 条件，也/还 + 结果",examples:[{zh:"哪怕只有一分钟，我也想见他。",en:"Even if it is only one minute, I still want to see him.",py:"Nǎpà zhǐyǒu yì fēnzhōng, wǒ yě xiǎng jiàn tā."},{zh:"哪怕失败，也要试一试。",en:"Even if we fail, we should try.",py:"Nǎpà shībài, yě yào shì yi shì."},{zh:"哪怕很忙，他也会给家里打电话。",en:"Even if he is very busy, he still calls home.",py:"Nǎpà hěn máng, tā yě huì gěi jiāli dǎ diànhuà."}],exercises:[{q:"填空：___失败，也要试一试。",a:"哪怕",instr:"填空",instrEn:"Fill in the blank",body:"___失败，也要试一试。"},{q:"翻译：Even if he is busy, he still calls home.",a:"哪怕很忙，他也会给家里打电话。",instr:"翻译",instrEn:"Translate",body:"Even if he is busy, he still calls home."},{q:"选择：表示极端让步条件用（哪怕 / 预先）。",a:"哪怕",instr:"选择",instrEn:"Choose",body:"表示极端让步条件用（哪怕 / 预先）。"}],note:"和“即使、即便”接近，口语和书面语都常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"nǎpà + condition, yě/hái + result = even if …, still …",noteEn:"Close to 即使/即便; common in both speech and writing.",typeEn:"Conjunction"},{id:"HSK6.32.2",name:"转折连接语“反之”",pinyin:"fǎnzhī",type:"连接语",explainEn:"Use 反之 to mean “conversely / the opposite is also true”.",structure:"A；反之，B（与A相反）",examples:[{zh:"运动有助于健康；反之，长期不运动会带来问题。",en:"Exercise helps health; conversely, long-term inactivity causes problems.",py:"Yùndòng yǒuzhùyú jiànkāng; fǎnzhī, chángqī bú yùndòng huì dàilái wèntí."},{zh:"信任能改善关系，反之，不信任会让关系更差。",en:"Trust can improve a relationship; conversely, distrust makes it worse.",py:"Xìnrèn néng gǎishàn guānxi, fǎnzhī, bú xìnrèn huì ràng guānxi gèng chà."},{zh:"准备充分更容易成功；反之，准备不足风险更大。",en:"Good preparation makes success more likely; conversely, poor preparation increases risk.",py:"Zhǔnbèi chōngfèn gèng róngyì chénggōng; fǎnzhī, zhǔnbèi bùzú fēngxiǎn gèng dà."}],exercises:[{q:"填空：信任能改善关系；___，不信任会让关系更差。",a:"反之",instr:"填空",instrEn:"Fill in the blank",body:"信任能改善关系；___，不信任会让关系更差。"},{q:"翻译：Conversely, poor preparation increases risk.",a:"反之，准备不足风险更大。",instr:"翻译",instrEn:"Translate",body:"Conversely, poor preparation increases risk."},{q:"用“反之”表达一个相反结果。",a:"认真准备更容易成功；反之，准备不足更容易失败。"}],note:"“反之”连接与前文相反的情况，后面常有停顿。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A; fǎnzhī, B (the opposite of A) = A; conversely, B",noteEn:"反之 introduces the opposite of the previous situation and is usually followed by a pause.",typeEn:"Linking phrase"}]},{num:33,title:"怀念慢生活",points:[{id:"HSK6.33.1",name:"固定格式“A的A，B的B”",pinyin:"A de A, B de B",type:"列举结构",explainEn:"Use A的A，B的B to list different people/things doing or showing different things.",structure:"动词/形容词 + 的 + 同一动词/形容词，……",examples:[{zh:"下课以后，看书的看书，聊天的聊天。",en:"After class, some read and some chat.",py:"Xiàkè yǐhòu, kàn shū de kàn shū, liáotiān de liáotiān."},{zh:"进了果园，红的红，绿的绿，漂亮极了。",en:"In the orchard, some fruit is red and some green; it is beautiful.",py:"Jìnle guǒyuán, hóng de hóng, lǜ de lǜ, piàoliang jí le."},{zh:"周末大家忙自己的，运动的运动，休息的休息。",en:"On weekends, everyone does their own thing: some exercise, some rest.",py:"Zhōumò dàjiā máng zìjǐ de, yùndòng de yùndòng, xiūxi de xiūxi."}],exercises:[{q:"填空：下课以后，看书___看书，聊天___聊天。",a:"的；的",instr:"填空",instrEn:"Fill in the blank",body:"下课以后，看书___看书，聊天___聊天。"},{q:"翻译：Some exercise and some rest.",a:"运动的运动，休息的休息。",instr:"翻译",instrEn:"Translate",body:"Some exercise and some rest."},{q:"用“A的A，B的B”描述：有人看电影，有人打电话。",a:"看电影的看电影，打电话的打电话。"}],note:"常用于口语，把同一场景中的不同情况并列列出来。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Verb/Adj + de + same Verb/Adj, … = some …, some … (listing what everyone is doing)",noteEn:"Common in speech; lists the different things going on in the same scene side by side.",typeEn:"Enumeration"},{id:"HSK6.33.2",name:"副词“一时”",pinyin:"yīshí",type:"副词",explainEn:"Use 一时 to mean “for a short time / temporarily”; repeated 一时…一时… can show alternating states.",structure:"一时 + 动词/状态；一时A，一时B",examples:[{zh:"这个名字我一时想不起来。",en:"I cannot remember this name for the moment.",py:"Zhège míngzi wǒ yìshí xiǎng bu qǐlái."},{zh:"听到这个消息，他一时不知道说什么。",en:"Hearing the news, he did not know what to say for a moment.",py:"Tīngdào zhège xiāoxi, tā yìshí bù zhīdào shuō shénme."},{zh:"天气一时晴，一时雨。",en:"The weather is sunny one moment and rainy the next.",py:"Tiānqì yìshí qíng, yìshí yǔ."}],exercises:[{q:"填空：这个名字我___想不起来。",a:"一时",instr:"填空",instrEn:"Fill in the blank",body:"这个名字我___想不起来。"},{q:"翻译：He did not know what to say for a moment.",a:"他一时不知道说什么。",instr:"翻译",instrEn:"Translate",body:"He did not know what to say for a moment."},{q:"用“一时……一时……”表达天气变化。",a:"天气一时晴，一时雨。"}],note:"既可表示短时间，也可重复使用表示状态交替。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yìshí + Verb/state; yìshí A, yìshí B = for a moment …; now A, now B",noteEn:"Can mean a short time, or, repeated, alternating states.",typeEn:"Adverb"}]},{num:34,title:"为文物而生的人",points:[{id:"HSK6.34.1",name:"连词“尚且”",pinyin:"shàngqiě",type:"连词",explainEn:"Use 尚且 in the first clause to say “even…”, then show that another case is even more obvious.",structure:"A + 尚且 + 谓语，何况/更 + B",examples:[{zh:"这么简单的问题他尚且不会，何况更难的呢？",en:"He cannot even do such an easy question, let alone a harder one.",py:"Zhème jiǎndān de wèntí tā shàngqiě bú huì, hékuàng gèng nán de ne?"},{zh:"成年人尚且会紧张，孩子就更不用说了。",en:"Even adults get nervous, let alone children.",py:"Chéngniánrén shàngqiě huì jǐnzhāng, háizi jiù gèng búyòng shuō le."},{zh:"经济好的时候公司尚且困难，现在就更难了。",en:"The company struggled even in good times; now it is even harder.",py:"Jīngjì hǎo de shíhou gōngsī shàngqiě kùnnan, xiànzài jiù gèng nán le."}],exercises:[{q:"填空：成年人___会紧张，孩子就更不用说了。",a:"尚且",instr:"填空",instrEn:"Fill in the blank",body:"成年人___会紧张，孩子就更不用说了。"},{q:"翻译：He cannot even do this easy question, let alone a harder one.",a:"这个简单问题他尚且不会，何况更难的。",instr:"翻译",instrEn:"Translate",body:"He cannot even do this easy question, let alone a harder one."},{q:"用“尚且”连接：大人都做不到，小孩更难。",a:"大人尚且做不到，小孩就更难了。"}],note:"前句提出一个已经很明显的例子，后句进一步推出更强结论。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"A + shàngqiě + predicate, hékuàng/gèng + B = even A …, let alone B",noteEn:"The first clause gives an already obvious example; the second draws an even stronger conclusion.",typeEn:"Conjunction"},{id:"HSK6.34.2",name:"介词/构词成分“当”",pinyin:"dāng",type:"介词/构词成分",explainEn:"Use 当 in words such as 当时、当地、当今、当场 to mean “at that time/place / present / on the spot”.",structure:"当 + 时/地/今/场……",examples:[{zh:"我至今还记得当时的情况。",en:"I still remember the situation at that time.",py:"Wǒ zhìjīn hái jìde dāngshí de qíngkuàng."},{zh:"这件事在当地很有名。",en:"This matter is well known locally.",py:"Zhè jiàn shì zài dāngdì hěn yǒumíng."},{zh:"他当场承认了错误。",en:"He admitted his mistake on the spot.",py:"Tā dāngchǎng chéngrènle cuòwù."}],exercises:[{q:"填空：我记得___时的情况。",a:"当",instr:"填空",instrEn:"Fill in the blank",body:"我记得___时的情况。"},{q:"翻译：He admitted his mistake on the spot.",a:"他当场承认了错误。",instr:"翻译",instrEn:"Translate",body:"He admitted his mistake on the spot."},{q:"选择：local people =（当地人 / 当时人）。",a:"当地人",instr:"选择",instrEn:"Choose",body:"local people =（当地人 / 当时人）。"}],note:"教材重点是“当+时间/地点成分”的用法，如当时、当地、当今、当场。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"dāng + shí/dì/jīn/chǎng … = at that time / local / nowadays / on the spot",noteEn:"The textbook focuses on 当 + time/place elements, as in 当时, 当地, 当今, 当场.",typeEn:"Preposition / Word-forming element"}]},{num:35,title:"走近木版年画",points:[{id:"HSK6.35.1",name:"副词“终究”",pinyin:"zhōngjiū",type:"副词",explainEn:"Use 终究 to mean “after all / in the end”; it stresses that the final result or nature will not change.",structure:"主语 + 终究 + 结果/判断",examples:[{zh:"问题终究会解决。",en:"The problem will be solved in the end.",py:"Wèntí zhōngjiū huì jiějué."},{zh:"假的终究是假的。",en:"What is false is false after all.",py:"Jiǎ de zhōngjiū shì jiǎ de."},{zh:"再困难的阶段终究会过去。",en:"Even a very difficult period will eventually pass.",py:"Zài kùnnan de jiēduàn zhōngjiū huì guòqu."}],exercises:[{q:"填空：问题___会解决。",a:"终究",instr:"填空",instrEn:"Fill in the blank",body:"问题___会解决。"},{q:"翻译：What is false is false after all.",a:"假的终究是假的。",instr:"翻译",instrEn:"Translate",body:"What is false is false after all."},{q:"选择：表示最终必然结果用（终究 / 不时）。",a:"终究",instr:"选择",instrEn:"Choose",body:"表示最终必然结果用（终究 / 不时）。"}],note:"强调最终结果、本质或不可否认的事实。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"Subject + zhōngjiū + result/judgment = after all / in the end …",noteEn:"Stresses the final result, the true nature, or an undeniable fact.",typeEn:"Adverb"},{id:"HSK6.35.2",name:"固定格式“愈……愈……”",pinyin:"yù ... yù ...",type:"程度结构",explainEn:"Use 愈…愈… to mean “the more…, the more…”. It is more formal than 越…越….",structure:"愈 + A，愈 + B",examples:[{zh:"事情愈复杂，愈需要冷静。",en:"The more complicated the matter, the more calm we need to be.",py:"Shìqing yù fùzá, yù xūyào lěngjìng."},{zh:"年纪愈大，愈重视健康。",en:"The older one gets, the more one values health.",py:"Niánjì yù dà, yù zhòngshì jiànkāng."},{zh:"了解得愈多，问题反而愈多。",en:"The more you understand, the more questions you may have.",py:"Liǎojiě de yù duō, wèntí fǎn'ér yù duō."}],exercises:[{q:"填空：事情___复杂，___需要冷静。",a:"愈；愈",instr:"填空",instrEn:"Fill in the blank",body:"事情___复杂，___需要冷静。"},{q:"翻译：The older one gets, the more one values health.",a:"年纪愈大，愈重视健康。",instr:"翻译",instrEn:"Translate",body:"The older one gets, the more one values health."},{q:"把“越学越有意思”改成较书面的表达。",a:"愈学愈有意思。"}],note:"和“越……越……”基本相同，但书面语色彩更强。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yù + A, yù + B = the more A, the more B",noteEn:"Basically the same as 越……越……, but more formal.",typeEn:"Degree structure"}]},{num:36,title:"中国古代书院",points:[{id:"HSK6.36.1",name:"副词“一经”",pinyin:"yījīng",type:"副词/条件结构",explainEn:"Use 一经 to mean “once”, showing that once an action happens, a result will follow.",structure:"一经 + 动作，就/便 + 结果",examples:[{zh:"这个规定一经公布，就立即生效。",en:"Once this rule is announced, it takes effect immediately.",py:"Zhège guīdìng yìjīng gōngbù, jiù lìjí shēngxiào."},{zh:"产品一经售出，不能随意退换。",en:"Once the product is sold, it cannot be returned freely.",py:"Chǎnpǐn yìjīng shòuchū, bù néng suíyì tuìhuàn."},{zh:"消息一经确认，我们就通知大家。",en:"Once the news is confirmed, we will inform everyone.",py:"Xiāoxi yìjīng quèrèn, wǒmen jiù tōngzhī dàjiā."}],exercises:[{q:"填空：规定___公布，就生效。",a:"一经",instr:"填空",instrEn:"Fill in the blank",body:"规定___公布，就生效。"},{q:"翻译：Once the news is confirmed, we will inform everyone.",a:"消息一经确认，我们就通知大家。",instr:"翻译",instrEn:"Translate",body:"Once the news is confirmed, we will inform everyone."},{q:"用“一经”改写：一旦售出，就不能退。",a:"产品一经售出，就不能退。"}],note:"较正式，常用于规则、新闻、说明等。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yìjīng + action, jiù/biàn + result = once …, then …",noteEn:"Fairly formal; common in rules, news and instructions.",typeEn:"Adverb / Conditional"},{id:"HSK6.36.2",name:"介词“本着 + 名词”",pinyin:"běnzhe + míngcí",type:"介词结构",explainEn:"Use 本着 + noun to mean “following / based on” a principle, spirit, purpose, or attitude.",structure:"本着 + 原则/精神/宗旨/态度 + 动词",examples:[{zh:"我们本着公平的原则处理问题。",en:"We handle the issue following the principle of fairness.",py:"Wǒmen běnzhe gōngpíng de yuánzé chǔlǐ wèntí."},{zh:"公司本着为客户负责的态度提供服务。",en:"The company provides service with a responsible attitude toward customers.",py:"Gōngsī běnzhe wèi kèhù fùzé de tàidu tígōng fúwù."},{zh:"双方本着合作精神继续讨论。",en:"Both sides continued discussions in a spirit of cooperation.",py:"Shuāngfāng běnzhe hézuò jīngshén jìxù tǎolùn."}],exercises:[{q:"填空：我们___公平的原则处理问题。",a:"本着",instr:"填空",instrEn:"Fill in the blank",body:"我们___公平的原则处理问题。"},{q:"翻译：Both sides continued in a spirit of cooperation.",a:"双方本着合作精神继续讨论。",instr:"翻译",instrEn:"Translate",body:"Both sides continued in a spirit of cooperation."},{q:"选择：常与“本着”搭配的是（原则 / 苹果）。",a:"原则",instr:"选择",instrEn:"Choose",body:"常与“本着”搭配的是（原则 / 苹果）。"}],note:"后面常接“原则、精神、宗旨、态度、方针、观点”等抽象名词。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"běnzhe + principle/spirit/aim/attitude + Verb = in line with … , do …",noteEn:"Usually followed by abstract nouns such as 原则, 精神, 宗旨, 态度, 方针, 观点.",typeEn:"Prep. phrase"}]},{num:37,title:"警察的故事",points:[{id:"HSK6.37.1",name:"固定格式“为……起见”",pinyin:"wèi ... qǐjiàn",type:"目的结构",explainEn:"Use 为…起见 to mean “for the sake of / in order to”. It is formal.",structure:"为 + 名词/动词/形容词 + 起见，主句",examples:[{zh:"为安全起见，请系好安全带。",en:"For safety, please fasten your seat belt.",py:"Wèi ānquán qǐjiàn, qǐng jìhǎo ānquándài."},{zh:"为方便起见，我们把资料放在网上。",en:"For convenience, we put the materials online.",py:"Wèi fāngbiàn qǐjiàn, wǒmen bǎ zīliào fàng zài wǎng shang."},{zh:"为保险起见，你最好再检查一遍。",en:"To be safe, you had better check again.",py:"Wèi bǎoxiǎn qǐjiàn, nǐ zuìhǎo zài jiǎnchá yí biàn."}],exercises:[{q:"填空：为安全___，请系安全带。",a:"起见",instr:"填空",instrEn:"Fill in the blank",body:"为安全___，请系安全带。"},{q:"翻译：For convenience, we put the materials online.",a:"为方便起见，我们把资料放在网上。",instr:"翻译",instrEn:"Translate",body:"For convenience, we put the materials online."},{q:"用“为……起见”表达：为了保险，再检查一次。",a:"为保险起见，再检查一遍。"}],note:"多用于正式建议、说明，强调采取措施的目的。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"wèi + Noun/Verb/Adj + qǐjiàn, main clause = for the sake of …, …",noteEn:"Mostly in formal advice or explanations; stresses the purpose of the measure taken.",typeEn:"Purpose structure"},{id:"HSK6.37.2",name:"副词“暂且”",pinyin:"zànqiě",type:"副词",explainEn:"Use 暂且 to mean “for the time being / for now”.",structure:"暂且 + 动词/判断",examples:[{zh:"这个问题暂且不谈。",en:"Let us not discuss this issue for now.",py:"Zhège wèntí zànqiě bù tán."},{zh:"没有更好的办法，我们暂且这样做。",en:"There is no better way, so we will do this for now.",py:"Méiyǒu gèng hǎo de bànfǎ, wǒmen zànqiě zhèyàng zuò."},{zh:"结果还没出来，暂且不能下结论。",en:"The result is not out yet, so we cannot conclude for now.",py:"Jiéguǒ hái méi chūlai, zànqiě bù néng xià jiélùn."}],exercises:[{q:"填空：这个问题___不谈。",a:"暂且",instr:"填空",instrEn:"Fill in the blank",body:"这个问题___不谈。"},{q:"翻译：We will do this for now.",a:"我们暂且这样做。",instr:"翻译",instrEn:"Translate",body:"We will do this for now."},{q:"选择：for the time being =（暂且 / 终究）。",a:"暂且",instr:"选择",instrEn:"Choose",body:"for the time being =（暂且 / 终究）。"}],note:"表示暂时先这样处理，以后可能改变。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"zànqiě + Verb/judgment = for now / for the time being",noteEn:"Handle it this way for now; it may change later.",typeEn:"Adverb"}]},{num:38,title:"慧眼捕捉商机",points:[{id:"HSK6.38.1",name:"副词“屡次”",pinyin:"lǚcì",type:"副词",explainEn:"Use 屡次 to mean “repeatedly / many times”, often for notable or negative events.",structure:"屡次 + 动词",examples:[{zh:"他屡次迟到，受到了批评。",en:"He was late repeatedly and was criticized.",py:"Tā lǚcì chídào, shòudàole pīpíng."},{zh:"这个问题屡次出现。",en:"This problem has appeared repeatedly.",py:"Zhège wèntí lǚcì chūxiàn."},{zh:"我们屡次提醒他注意安全。",en:"We repeatedly reminded him to pay attention to safety.",py:"Wǒmen lǚcì tíxǐng tā zhùyì ānquán."}],exercises:[{q:"填空：这个问题___出现。",a:"屡次",instr:"填空",instrEn:"Fill in the blank",body:"这个问题___出现。"},{q:"翻译：We repeatedly reminded him.",a:"我们屡次提醒他。",instr:"翻译",instrEn:"Translate",body:"We repeatedly reminded him."},{q:"选择：repeatedly =（屡次 / 一时）。",a:"屡次",instr:"选择",instrEn:"Choose",body:"repeatedly =（屡次 / 一时）。"}],note:"比“多次”更书面，常强调同类事情反复发生。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"lǚcì + Verb = repeatedly …",noteEn:"More formal than 多次; stresses that the same kind of thing keeps happening.",typeEn:"Adverb"},{id:"HSK6.38.2",name:"“依据”表示根据",pinyin:"yījù",type:"名词/动词/介词",explainEn:"Use 依据 to mean “basis / according to / base on”.",structure:"依据 + 材料/规则 + 动词；以……为依据",examples:[{zh:"我们依据数据做出了判断。",en:"We made the judgment based on data.",py:"Wǒmen yījù shùjù zuòchūle pànduàn."},{zh:"这个结论有充分的事实依据。",en:"This conclusion has sufficient factual basis.",py:"Zhège jiélùn yǒu chōngfèn de shìshí yījù."},{zh:"请以合同为依据处理这个问题。",en:"Please handle this issue based on the contract.",py:"Qǐng yǐ hétong wéi yījù chǔlǐ zhège wèntí."}],exercises:[{q:"填空：我们___数据做判断。",a:"依据",instr:"填空",instrEn:"Fill in the blank",body:"我们___数据做判断。"},{q:"翻译：This conclusion has a factual basis.",a:"这个结论有事实依据。",instr:"翻译",instrEn:"Translate",body:"This conclusion has a factual basis."},{q:"用“以……为依据”表达：按照合同处理。",a:"以合同为依据处理。"}],note:"既可作名词，也可作动词/介词性用法；常用于正式论证。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"yījù + material/rule + Verb; yǐ … wéi yījù = according to …; take … as the basis",noteEn:"Works as a noun or as a verb/preposition; common in formal argument.",typeEn:"Noun / Verb / Preposition"}]},{num:39,title:"互联网时代的生活",points:[{id:"HSK6.39.1",name:"副词/形容词“任意”",pinyin:"rènyì",type:"副词/形容词",explainEn:"Use 任意 to mean “any / freely / at will”.",structure:"任意 + 动词；任意 + 名词",examples:[{zh:"你可以任意选择一种方式。",en:"You may freely choose any method.",py:"Nǐ kěyǐ rènyì xuǎnzé yì zhǒng fāngshì."},{zh:"不能任意修改数据。",en:"You cannot change the data at will.",py:"Bù néng rènyì xiūgǎi shùjù."},{zh:"从任意一个入口都可以进去。",en:"You can enter through any entrance.",py:"Cóng rènyì yí ge rùkǒu dōu kěyǐ jìnqu."}],exercises:[{q:"填空：你可以___选择。",a:"任意",instr:"填空",instrEn:"Fill in the blank",body:"你可以___选择。"},{q:"翻译：You cannot change the data at will.",a:"不能任意修改数据。",instr:"翻译",instrEn:"Translate",body:"You cannot change the data at will."},{q:"选择：any entrance =（任意一个入口 / 预先一个入口）。",a:"任意一个入口",instr:"选择",instrEn:"Choose",body:"any entrance =（任意一个入口 / 预先一个入口）。"}],note:"表示没有特别限制，可自由选择；正式语体常见。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"rènyì + Verb; rènyì + Noun = … freely / at will; any …",noteEn:"No particular limit — free to choose; common in formal style.",typeEn:"Adverb / Adjective"},{id:"HSK6.39.2",name:"副词“尚未”",pinyin:"shàngwèi",type:"副词",explainEn:"Use 尚未 to mean “have not yet”. It is more formal than 还没.",structure:"尚未 + 动词",examples:[{zh:"结果尚未公布。",en:"The result has not yet been announced.",py:"Jiéguǒ shàngwèi gōngbù."},{zh:"这个问题尚未解决。",en:"This problem has not yet been solved.",py:"Zhège wèntí shàngwèi jiějué."},{zh:"双方尚未达成一致。",en:"The two sides have not yet reached agreement.",py:"Shuāngfāng shàngwèi dáchéng yízhì."}],exercises:[{q:"填空：结果___公布。",a:"尚未",instr:"填空",instrEn:"Fill in the blank",body:"结果___公布。"},{q:"翻译：This problem has not yet been solved.",a:"这个问题尚未解决。",instr:"翻译",instrEn:"Translate",body:"This problem has not yet been solved."},{q:"把“还没达成一致”改成较正式的表达。",a:"尚未达成一致。"}],note:"常见于新闻、报告、正式说明。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"shàngwèi + Verb = has not yet …",noteEn:"Common in news, reports and formal statements.",typeEn:"Adverb"}]},{num:40,title:"人类超能力会改变世界纪录吗",points:[{id:"HSK6.40.1",name:"固定格式“（把）……放在眼里”",pinyin:"(bǎ) ... fàng zài yǎnlǐ",type:"固定格式",explainEn:"Use （把）…放在眼里 to mean “take…seriously / consider…important”, often in the negative.",structure:"把 + 人/事 + 放在眼里；不把……放在眼里",examples:[{zh:"他根本没把这个困难放在眼里。",en:"He did not take this difficulty seriously at all.",py:"Tā gēnběn méi bǎ zhège kùnnan fàng zài yǎn li."},{zh:"你不能不把安全放在眼里。",en:"You cannot ignore safety.",py:"Nǐ bù néng bù bǎ ānquán fàng zài yǎn li."},{zh:"他太骄傲，谁都不放在眼里。",en:"He is so proud that he looks down on everyone.",py:"Tā tài jiāo'ào, shéi dōu bú fàng zài yǎn li."}],exercises:[{q:"填空：他没把困难放在___。",a:"眼里",instr:"填空",instrEn:"Fill in the blank",body:"他没把困难放在___。"},{q:"翻译：He looks down on everyone.",a:"他谁都不放在眼里。",instr:"翻译",instrEn:"Translate",body:"He looks down on everyone."},{q:"用该格式表达：不能忽视安全。",a:"不能不把安全放在眼里。"}],note:"否定形式很常见，可表示“不重视”或“看不起某人”。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bǎ + person/thing + fàng zài yǎn li; bù bǎ … fàng zài yǎn li = take … seriously; look down on …",noteEn:'The negative form is very common: "not take seriously" or "look down on someone".',typeEn:"Fixed pattern"},{id:"HSK6.40.2",name:"“不无”表示并非没有",pinyin:"bùwú",type:"动词/书面否定",explainEn:"Use 不无 to mean “not without / there is some…”. It is formal.",structure:"不无 + 道理/遗憾/可能/影响",examples:[{zh:"他的说法不无道理。",en:"What he said is not without reason.",py:"Tā de shuōfǎ bùwú dàoli."},{zh:"这次失败不无遗憾。",en:"This failure is not without regret.",py:"Zhè cì shībài bùwú yíhàn."},{zh:"这种变化不无可能。",en:"This change is not impossible.",py:"Zhè zhǒng biànhuà bùwú kěnéng."}],exercises:[{q:"填空：他的说法___道理。",a:"不无",instr:"填空",instrEn:"Fill in the blank",body:"他的说法___道理。"},{q:"翻译：This change is not impossible.",a:"这种变化不无可能。",instr:"翻译",instrEn:"Translate",body:"This change is not impossible."},{q:"选择：表示“有一定道理”可说（不无道理 / 尚未道理）。",a:"不无道理",instr:"选择",instrEn:"Choose",body:"表示“有一定道理”可说（不无道理 / 尚未道理）。"}],note:"双重否定式书面表达，语气通常比直接说“有”更委婉。",source:"https://courses.chinesezerotohero.com/p/hsk-6-course",structureEn:"bùwú + dàoli/yíhàn/kěnéng/yǐngxiǎng = not without (some) reason/regret/possibility/effect",noteEn:"A formal double negative; usually more tactful than simply saying 有.",typeEn:"Verb / Formal negation"}]}],s={series:e,unit:6,lessons:n};export{s as default,n as lessons,e as series,t as unit};
